def _log_filter_str(name_to_value):
    """return a map from name to value into a log filter query that requires
    each name to equal the given value."""
    return ' AND '.join(
        '%s = %s' % (name, _quote_filter_value(value))
        for name, value in sorted(name_to_value.items()))

def _quote_filter_value(s):
    """Put a string in double quotes, escaping double quote characters"""
    return '"%s"' % s.replace('"', r'\"')

def _fully_qualify_scope_uri(uri):
    if is_uri(uri):
        return uri
    else:
        return 'https://www.googleapis.com/auth/%s' % uri

def _basename(path_or_uri):
    if is_uri(path_or_uri):
        return posixpath.basename(path_or_uri)
    else:
        return os.path.basename(path_or_uri)

def is_uri(uri):
    r"""Return True if *uri* is a URI and contains ``://``
    (we only care about URIs that can describe files)
    """
    return '://' in uri and bool(urlparse(uri).scheme)

def can_handle_path(self, path):
    if not (self._hadoop_bin or self._hadoop_bin is None):
        return False

    return is_uri(path)

def join(self, path, *paths):
    """Join *paths* onto *path* (which may be a URI)"""
    from mrjob.parse import urlparse
    from mrjob.parse import is_uri
    all_paths = (path,) + paths

    # if there's a URI, we only care about it and what follows
    for i in range(len(all_paths), 0, -1):
        if is_uri(all_paths[i - 1]):
            scheme, netloc, uri_path = urlparse(all_paths[i - 1])[:3]
            return '%s://%s%s' % (
                scheme, netloc, posixpath.join(
                    uri_path or '/', *all_paths[i:]))
    else:
        return os.path.join(*all_paths)

