            option_string, value))

    try:
        v = json.loads(v)
    except ValueError:
        if _PROBABLY_JSON_RE.match(v):
            parser.error('%s argument %r is not valid JSON' % (
                option_string, value))

    _default_to(namespace, self.dest, {})
    getattr(namespace, self.dest)[k] = v

