def _find_hadoop_streaming_jar(self):
    """Search for the hadoop streaming jar. See
    :py:meth:`_hadoop_streaming_jar_dirs` for where we search."""
    for path in unique(self._hadoop_streaming_jar_dirs()):
        log.info('Looking for Hadoop streaming jar in %s...' % path)

        streaming_jars = []
        for path in self.fs.ls(path):
            if _HADOOP_STREAMING_JAR_RE.match(posixpath.basename(path)):
                streaming_jars.append(path)

        if streaming_jars:
            # prefer shorter names and shallower paths
            def sort_key(p):
                return (len(p.split('/')),
                        len(posixpath.basename(p)),
                        p)

            streaming_jars.sort(key=sort_key)

            return streaming_jars[0]

    return None

def _hadoop_streaming_jar_dirs(self):
    """Yield all possible places to look for the Hadoop streaming jar.
    May yield duplicates.
    """
    for hadoop_dir in self._hadoop_dirs():
        yield hadoop_dir

    # use hard-coded paths to work out-of-the-box on EMR
    for path in _EMR_HADOOP_STREAMING_JAR_DIRS:
        yield path

def _hadoop_dirs(self):
    """Yield all possible hadoop directories (used for streaming jar
    and logs). May yield duplicates"""
    for name in ('HADOOP_PREFIX', 'HADOOP_HOME', 'HADOOP_INSTALL',
                 'HADOOP_MAPRED_HOME'):
        path = os.environ.get(name)
        if path:
            yield path

    # guess it from the path of the Hadoop binary
    hadoop_home = _hadoop_prefix_from_bin(self.get_hadoop_bin()[0])
    if hadoop_home:
        yield hadoop_home

    # try HADOOP_*_HOME
    for name, path in sorted(os.environ.items()):
        if name.startswith('HADOOP_') and name.endswith('_HOME'):
            yield path

def which(cmd, path=None):
    """Like the UNIX which command: search in *path* for the executable named
    *cmd*. *path* defaults to :envvar:`PATH`. Returns ``None`` if no
    such executable found.

    This is basically ``shutil.which()`` (which was introduced in Python 3.3)
    without the *mode* argument. Best practice is to always specify *path*
    as a keyword argument.
    """
    if hasattr(shutil, 'which'):
        # added in Python 3.3
        return shutil.which(cmd, path=path)
    elif path is None and os.environ.get('PATH') is None:
        # find_executable() errors if neither path nor $PATH is set
        return None
    else:
        return find_executable(cmd, path=path)

def _find_hadoop_bin(self):
    """Look for the hadoop binary in any plausible place. If all
    else fails, return ``['hadoop']``.
    """
    def yield_paths():
        for name in 'HADOOP_PREFIX', 'HADOOP_HOME', 'HADOOP_INSTALL':
            path = os.environ.get(name)
            if path:
                yield os.path.join(path, 'bin')

        # They use $HADOOP_INSTALL/hadoop/bin here:
        # https://wiki.apache.org/hadoop/GettingStartedWithHadoop
        if os.environ.get('HADOOP_INSTALL'):
            yield os.path.join(
                os.environ['HADOOP_INSTALL'], 'hadoop', 'bin')

        yield None  # use $PATH

        # Maybe it's in $HADOOP_MAPRED_HOME? $HADOOP_YARN_HOME? Don't give
        # up. Don't worry about duplicates; they're de-duplicated below
        for name, path in sorted(os.environ.items()):
            if name.startswith('HADOOP_') and name.endswith('_HOME'):
                yield os.path.join(path, 'bin')

    for path in unique(yield_paths()):
        log.info('Looking for hadoop binary in %s...' % (path or '$PATH'))

        hadoop_bin = which('hadoop', path=path)

        if hadoop_bin:
            log.info('Found hadoop binary: %s' % hadoop_bin)
            return [hadoop_bin]
    else:
        log.info("Falling back to 'hadoop'")
        return ['hadoop']

def yield_paths():
    for name in 'HADOOP_PREFIX', 'HADOOP_HOME', 'HADOOP_INSTALL':
        path = os.environ.get(name)
        if path:
            yield os.path.join(path, 'bin')

    # They use $HADOOP_INSTALL/hadoop/bin here:
    # https://wiki.apache.org/hadoop/GettingStartedWithHadoop
    if os.environ.get('HADOOP_INSTALL'):
        yield os.path.join(
            os.environ['HADOOP_INSTALL'], 'hadoop', 'bin')

    yield None  # use $PATH

    # Maybe it's in $HADOOP_MAPRED_HOME? $HADOOP_YARN_HOME? Don't give
    # up. Don't worry about duplicates; they're de-duplicated below
    for name, path in sorted(os.environ.items()):
        if name.startswith('HADOOP_') and name.endswith('_HOME'):
            yield os.path.join(path, 'bin')

def _hadoop_log_dirs(self, output_dir=None):
    """Yield all possible places to look for hadoop logs."""
    # hadoop_log_dirs opt overrides all this
    if self._opts['hadoop_log_dirs']:
        for path in self._opts['hadoop_log_dirs']:
            yield path
        return

    hadoop_log_dir = os.environ.get('HADOOP_LOG_DIR')
    if hadoop_log_dir:
        yield hadoop_log_dir

    yarn = uses_yarn(self.get_hadoop_version())

    if yarn:
        yarn_log_dir = os.environ.get('YARN_LOG_DIR')
        if yarn_log_dir:
            yield yarn_log_dir

        yield _DEFAULT_YARN_HDFS_LOG_DIR

    if output_dir:
        # Cloudera style of logging
        yield posixpath.join(output_dir, '_logs')

    for hadoop_dir in self._hadoop_dirs():
        yield posixpath.join(hadoop_dir, 'logs')

    # hard-coded fallback paths
    if yarn:
        for path in _FALLBACK_HADOOP_YARN_LOG_DIRS:
            yield path

    for path in _FALLBACK_HADOOP_LOG_DIRS:
        yield path

def _stream_history_log_dirs(self, output_dir=None):
    """Yield lists of directories to look for the history log in."""
    if not self._read_logs():
        return

    for log_dir in unique(self._hadoop_log_dirs(output_dir=output_dir)):
        if _logs_exist(self.fs, log_dir):
            log.info('Looking for history log in %s...' % log_dir)
            # logs aren't always in a subdir named history/
            yield [log_dir]

def _stream_task_log_dirs(self, application_id=None, output_dir=None):
    """Yield lists of directories to look for the task logs in."""
    # Note: this is unlikely to be super-helpful on "real" (multi-node)
    # pre-YARN Hadoop because task logs aren't generally shipped to a
    # local directory. It's a start, anyways. See #1201.
    if not self._read_logs():
        return

    for log_dir in unique(self._hadoop_log_dirs(output_dir=output_dir)):
        if application_id:
            path = self.fs.join(log_dir, 'userlogs', application_id)
        else:
            path = self.fs.join(log_dir, 'userlogs')

        if _logs_exist(self.fs, path):
            log.info('Looking for task syslogs in %s...' % path)
            yield [path]

def unique(items):
    """Yield items from *item* in order, skipping duplicates."""
    seen = set()

    for item in items:
        if item in seen:
            continue
        else:
            yield item
            seen.add(item)

def _logs_exist(fs, path):
    """Do ``fs.exists(path)``, and return ``None`` if it raises ``IOError``"""
    try:
        return fs.exists(path)
    except IOError:
        return None

def _add_job_files_for_upload(self):
    """Add files needed for running the job (setup and input)
    to self._upload_mgr."""
    for path in self._py_files():
        self._upload_mgr.add(path)

def _default_python_bin(self, local=False):
    """Always return *sys.executable*, if defined"""
    return super(LocalMRJobRunner, self)._default_python_bin(
        local=True)

def _is_counter_log4j_record(record):
    """Is this the record containing counters?

    (HadoopJobRunner doesn't want to log this because it's very long
    and it has its own way of displaying counters.)
    """
    return bool(_INDENTED_COUNTERS_MESSAGE_RE.match(record['message']))

def _spark_master(self):
    # hard-coded for EMR
    return 'yarn'

def _spark_deploy_mode(self):
    # hard-coded for EMR; otherwise it can't access S3
    return 'cluster'

def _run_step(self, step, step_num):
    """Run an individual step. You can assume that setup wrapper scripts
    are created and self._counters has a dictionary for that step already.
    """
    if _is_spark_step_type(step['type']):
        self._run_step_on_spark(step, step_num)
    else:
        self._run_streaming_step(step, step_num)

def _step_type_uses_spark(self, step_type):
    """Does this step run on Spark?

    (This is re-defined in the Spark runner to include
    streaming steps, and used by mrjob.logs.mixin)
    """
    return _is_spark_step_type(step_type)

def _is_spark_step_type(step_type):
    """Does the given step type indicate that it uses Spark?"""
    return step_type.split('_')[0] == 'spark'

def sort_key(p):
    return (len(p.split('/')),
            len(posixpath.basename(p)),
            p)

def _sort_reducer_input(self, step_num, num_map_tasks):
    step = self._get_step(step_num)

    output_path = self._sorted_reducer_input_path(step_num)
    self.fs.mkdir(dirname(output_path))

    prev_task_type = 'combiner' if step.get('combiner') else 'mapper'
    input_paths = [
        self._task_output_path(prev_task_type, step_num, task_num)
        for task_num in range(num_map_tasks)
    ]

    self._sort_input_func()(input_paths, output_path)

def _sort_input_func(self):
    """Try sorting with the :command:`sort` binary before falling
    back to in-memory sort."""
    if platform.system() == 'Windows':  # we assume Unix sort
        return super(LocalMRJobRunner, self)._sort_input_func()
    else:
        return partial(
            _sort_lines_with_sort_bin,
            sort_bin=self._sort_bin(),
            tmp_dir=self._get_local_tmp_dir())

def _sort_bin(self):
    """The binary to use to sort input.

    (On Windows, we go straight to sorting in memory.)
    """
    if self._opts['sort_bin']:
        return self._opts['sort_bin']
    elif self._sort_values:
        return ['sort']
    else:
        # only sort on the reducer key (see #660)
        return ['sort', '-t', '\t', '-k', '1,1', '-s']

def _opt_combiners(self):
    """Combine *cmdenv* with :py:func:`~mrjob.conf.combine_local_envs`"""
    return combine_dicts(
        super(SimMRJobRunner, self)._opt_combiners(),
        dict(cmdenv=combine_local_envs),
    )

def to_env(jobconf):
    return dict((k.replace('.', '_'), str(v))
                for k, v in jobconf.items())

def combine_local_envs(*envs):
    """Same as :py:func:`combine_envs`, except that paths are combined
    using the local path separator (e.g ``;`` on Windows rather than ``:``).
    """
    return _combine_envs_helper(envs, local=True)

def _combine_envs_helper(envs, local):
    if local:
        pathsep = os.pathsep
    else:
        pathsep = ':'

    result = {}
    for env in envs:
        if env:
            for k, v in env.items():
                # delete cleared keys
                if isinstance(v, ClearedValue) and v.value is None:
                    result.pop(k, None)

                # append paths
                elif (k.endswith('PATH') and result.get(k) and
                      not isinstance(v, ClearedValue)):
                    result[k] = v + pathsep + result[k]

                # just set the value
                else:
                    result[k] = _strip_clear_tag(v)

    return result

def _run_multiple(self, funcs, num_processes=None):
    """Run multiple no-args functions, possibly in parallel using
    :py:mod:`multiprocessing` (if so all *funcs* must be pickleable).

    By default, we just call *funcs* one at a time
    """
    for func in funcs:
        func()

def _log_cause_of_error(self, ex):
    """Log why the job failed."""
    pass

def _run_mappers_and_combiners(self, step_num, map_splits):
    try:
        self._run_multiple(
            self._run_mapper_and_combiner_func(
                step_num, task_num, map_split)
            for task_num, map_split in enumerate(map_splits)
        )
    finally:
        self._parse_task_counters('mapper', step_num)
        self._parse_task_counters('combiner', step_num)

def _run_reducers(self, step_num, num_reducer_tasks):
    try:
        self._run_multiple(
            self._run_task_func('reducer', step_num, task_num)
            for task_num in range(num_reducer_tasks)
        )
    finally:
        self._parse_task_counters('reducer', step_num)

def _setup_working_dir(self, task_type, step_num, task_num):
    wd = self._task_working_dir(task_type, step_num, task_num)
    self.fs.mkdir(wd)

    for type in ('archive', 'file'):
        for name, path in (
                self._working_dir_mgr.name_to_path(type).items()):
            _symlink_or_copy(
                self._path_in_dist_cache_dir(name, step_num),
                join(wd, name))

    return wd

def _task_input_path(self, task_type, step_num, task_num):
    return join(
        self._task_dir(task_type, step_num, task_num), 'input')

def _task_stderr_path(self, task_type, step_num, task_num):
    return join(
        self._task_dir(task_type, step_num, task_num), 'stderr')

def _task_output_path(self, task_type, step_num, task_num):
    """Where to output data for the given task.

    Usually this is just a file named "output" in the task's directory,
    but if it's the last task type in the step (usually the reducer),
    it outputs directly to part-XXXXX files in the step's output directory.
    """
    if task_type == self._last_task_type_in_step(step_num):
        return join(
            self._output_dir_for_step(step_num), 'part-%05d' % task_num)
    else:
        return join(
            self._task_dir(task_type, step_num, task_num), 'output')

def _task_stderr_paths_glob(self, task_type, step_num):
    return join(
        self._step_dir(step_num), task_type, '*', 'stderr')

def _log_counters(self, step_num):
    counters = self.counters()[step_num]
    if counters:
        log.info('\n%s\n' % _format_counters(counters))

def _format_counters(counters, indent='\t', desc='Counters'):
    """Convert a map from group -> counter name -> amount to a message
    similar to that printed by the Hadoop binary, with no trailing newline.
    """
    num_counters = sum(len(counter_to_amount)
                       for group, counter_to_amount in counters.items())
    message = '%s: %d' % (desc, num_counters)

    for group, group_counters in sorted(counters.items()):
        if group_counters:
            message += '\n%s%s' % (indent, group)
            for counter, amount in sorted(group_counters.items()):
                message += '\n%s%s%s=%d' % (indent, indent, counter, amount)

    return message

def _log_counters(self, log_interpretation, step_num):
    """Utility for logging counters (if any) for a step."""
    step_type = self._get_step(step_num)['type']

    if not self._step_type_uses_spark(step_type):
        counters = self._pick_counters(
            log_interpretation, step_type)
        if counters:
            log.info(_format_counters(counters))
        elif self._read_logs():
            # should only log this if we actually looked for counters
            log.warning('No counters found')

def _sort_values_jobconf(self):
    """Jobconf dictionary to enable sorting by value.
    """
    if not self._sort_values:
        return {}

    # translate _SORT_VALUES_JOBCONF to the correct Hadoop version,
    # without logging a warning
    hadoop_version = self.get_hadoop_version()

    jobconf = {}
    for k, v in _SORT_VALUES_JOBCONF.items():
        if hadoop_version:
            jobconf[translate_jobconf(k, hadoop_version)] = v
        else:
            for j in translate_jobconf_for_all_versions(k):
                jobconf[j] = v

    return jobconf

def translate_jobconf(variable, version):
    """Translate *variable* to Hadoop version *version*. If it's not
    a variable we recognize, leave as-is.
    """
    if version is None:
        raise TypeError

    if variable in _JOBCONF_MAP:
        return map_version(version, _JOBCONF_MAP[variable])
    else:
        return variable

def translate_jobconf_for_all_versions(variable):
    """Get all known variants of the given jobconf variable.
    Unlike :py:func:`translate_jobconf`, returns a list."""
    return sorted(
        set([variable] + list(_JOBCONF_MAP.get(variable, {}).values())))

def _chmod_u_rx(path, recursive=False):
    """make *path* user readable and executable. If *recursive* is true,
    make *path* and everything inside it executable."""
    if recursive:
        for dir_name, _, file_names in os.walk(path, followlinks=True):
            for file_name in file_names:
                _chmod_u_rx(join(dir_name, file_name))
    else:
        # only available on Unix, causes rmtree() to fail on Windows; see #1847
        if hasattr(os, 'chmod') and platform.system() != "Windows":
            os.chmod(path, stat.S_IRUSR | stat.S_IXUSR)

def _num_mappers(self, step_num):
    # TODO: look up mapred.job.maps (convert to int) in _jobconf_for_step()
    return self._num_cores()

def _num_reducers(self, step_num):
    # TODO: look up mapred.job.reduces in _jobconf_for_step()
    return self._num_cores()

def _pick_mapper_split_size(self, input_paths, step_num):
    if not isinstance(input_paths, list):
        raise TypeError

    target_num_splits = self._num_mappers(step_num) * 2

    # decide on a split size to approximate target_num_splits
    num_compressed = 0
    uncompressed_bytes = 0

    for path in input_paths:
        if path.endswith('.gz') or path.endswith('.bz'):
            num_compressed += 1
        else:
            uncompressed_bytes += os.stat(path)[stat.ST_SIZE]

    return uncompressed_bytes // max(
        target_num_splits - num_compressed, 1)

def _run_mapper_and_combiner(
        run_mapper, sort_input, run_combiner,
        mapper_input_path, mapper_output_path, combiner_input_path):
    """Helper for :py:meth:`SimMRJobRunner._run_mapper_and_combiner_func`."""
    # we don't need *combiner_output_path* because *run_combiner* already
    # knows it

    if run_mapper:
        run_mapper()
    else:
        _symlink_or_copy(mapper_input_path, mapper_output_path)

    if run_combiner:
        sort_input([mapper_output_path], combiner_input_path)
        run_combiner()

def _symlink_or_copy(path, dest):
    """Symlink from *dest* to *path*, using relative paths if possible.

    If symlinks aren't available, copy path to dest instead.
    """
    if hasattr(os, 'symlink'):
        log.debug('creating symlink %s <- %s' % (path, dest))
        try:
            os.symlink(relpath(path, dirname(dest)), dest)
            return
        except OSError as ex:
            log.debug('  %s' % ex)

    log.debug('copying %s -> %s' % (dest, path))
    if isdir(path):
        copytree(path, dest)
    else:
        copy2(path, dest)

def _check_step(self, step, step_num):
    """Don't try to run steps that include commands."""
    super(InlineMRJobRunner, self)._check_step(step, step_num)

    if step['type'] == 'streaming':
        for mrc in ('mapper', 'combiner', 'reducer'):
            if step.get(mrc):
                if 'command' in step[mrc] or 'pre_filter' in step[mrc]:
                    raise NotImplementedError(
                        "step %d's %s runs a command, but inline"
                        " runner does not support subprocesses (try"
                        " -r local)" % (step_num, mrc))

def _has_hadoop_streaming_steps(self):
    """Are any of our steps Hadoop Streaming steps?"""
    return any(step['type'] == 'streaming'
               for step in self._get_steps())

def _uses_input_manifest(self):
    """Does the first step take an input manifest?"""
    return bool(self._get_step(0).get('input_manifest'))

def _cmdenv(self):
    """Return a copy of ``self._opts['cmdenv']``. This exists so we
    can instrument cmdenv in runner subclasses."""
    return dict(self._opts['cmdenv'])

def _sort_values_partitioner(self):
    """Partitioner to use with *sort_values* keyword to the constructor."""
    if self._sort_values:
        return _SORT_VALUES_PARTITIONER
    else:
        return None

def _log_cause_of_error(self, ex):
    """Just tell what file we were reading from (since they'll see
    the stacktrace from the actual exception)"""
    if self._error_while_reading_from:
        log.error('\nError while reading from %s:\n' %
                  self._error_while_reading_from)

def __str__(self):
    """Human-readable version of the exception. Note that this 1-indexes
    *step_num*."""
    if self.step_desc:
        step_desc = self.step_desc
    else:
        if self.step_num is not None:
            # 1-index step numbers
            if self.last_step_num is not None:
                step_name = 'Steps %d-%d' % (
                    self.step_num + 1, self.last_step_num + 1)
            else:
                step_name = 'Step %d' % (self.step_num + 1)

            if self.num_steps:
                step_desc = '%s of %d' % (step_name, self.num_steps)
            else:
                step_desc = step_name
        else:
            step_desc = 'Step'

    if self.reason:
        return '%s failed: %s' % (step_desc, self.reason)
    else:
        return '%s failed' % step_desc

def _resolve_path(path):
    """Helper for :py:func:`parse_setup_cmd`.

    Resolve ``~`` (home dir) and environment variables in the
    given path, and unescape backslashes."""
    result = ''

    for m in _ESCAPE_RE.finditer(path):
        if m.group('escaped'):
            result += m.group('escaped')
        elif m.group('unescaped'):
            result += expand_path(m.group('unescaped'))
        else:
            raise ValueError('No escaped character')

    return result

def _combine_opts(self, opt_list):
    """Propagate *instance_type* to other instance type opts, if not
    already set.

    Also propagate core instance type to task instance type, if it's
    not already set.
    """
    opts = super(HadoopInTheCloudJobRunner, self)._combine_opts(opt_list)

    if opts['instance_type']:
        # figure out how late in the configs opt was set (setting
        # --instance_type on the command line overrides core_instance_type
        # set in configs)
        opt_priority = {k: -1 for k in opts}

        for i, sub_opts in enumerate(opt_list):
            for k, v in sub_opts.items():
                if v == opts[k]:
                    opt_priority[k] = i

        # instance_type only affects master_instance_type if there are
        # no other instances
        if opts['num_core_instances'] or opts['num_task_instances']:
            propagate_to = ['core_instance_type', 'task_instance_type']
        else:
            propagate_to = ['master_instance_type']

        for k in propagate_to:
            if opts[k] is None or (
                    opt_priority[k] < opt_priority['instance_type']):
                opts[k] = opts['instance_type']

    if not opts['task_instance_type']:
        opts['task_instance_type'] = opts['core_instance_type']

    return opts

def _default_instance_type(self):
    """Default instance type if not set by the user."""
    # m5.xlarge is available on all regions, but only works in AMI 5.13.0
    # or later. See #2098.
    if self._image_version_gte('5.13.0'):
        return 'm5.xlarge'
    else:
        return 'm4.large'

def _unarchive_cmd(path):
    """Look up the unarchive command to use with the given file extension,
    or raise KeyError if there is no matching command."""
    for ext, unarchive_cmd in sorted(_EXT_TO_UNARCHIVE_CMD.items()):
        # use this so we can match e.g. mrjob-0.7.0.tar.gz
        if path.endswith(ext):
            return unarchive_cmd

    raise KeyError('unknown archive type: %s' % path)

def _sh_bin(self):
    """The sh binary and any arguments, as a list. Override this
    if, for example, a runner needs different default values
    depending on circumstances (see :py:class:`~mrjob.emr.EMRJobRunner`).
    """
    return self._opts['sh_bin'] or self._default_sh_bin()

def _default_sh_bin(self):
    """The default sh binary, if :mrjob-opt:`sh_bin` isn't set."""
    return ['/bin/sh', '-ex']

def _patch_params(params, name, value):
    """Helper method for _add_extra_cluster_params().

    Set *name* in *params* to *value*

    If *name* has one or more dots in it, recursively set the value
    in successive nested dictionaries, creating them if necessary.
    For example, if *name* is ``Instances.EmrManagedMasterSecurityGroup``,
    set ``params['Instances']['EmrManagedMasterSecurityGroup']``

    If *value* is ``None``, delete the value (if it exists), rather than
    setting it to ``None``.
    """
    if not isinstance(params, dict):
        raise TypeError('must be a dictionary')

    if '.' in name:
        head, rest = name.split('.', 1)
        _patch_params(params.setdefault(head, {}), rest, value)
    elif value is None:
        if name in params:
            del params[name]
    elif isinstance(value, dict) and isinstance(params.get(name), dict):
        # recursively patch dicts rather than clobbering them (see #2154)
        for k, v in value.items():
            _patch_params(params[name], k, v)
    else:
        params[name] = value

def _launch_ssh_proc(self, args):
    """The command used to create a :py:class:`subprocess.Popen` to
    run the SSH tunnel. You usually don't need to redefine this."""
    log.debug('> %s' % cmd_line(args))
    return Popen(args, stdin=PIPE, stdout=PIPE, stderr=PIPE)

def _default_python_bin(self, local=False):
    """The default python command. If local is true, try to use
    sys.executable. Otherwise use 'python2.7' or 'python3' as appropriate.

    This returns a single-item list (because it's a command).
    """
    is_pypy = (python_implementation() == 'PyPy')

    if local and sys.executable:
        return [sys.executable]
    else:
        if PY2:
            return ['pypy'] if is_pypy else ['python2.7']
        else:
            return ['pypy3'] if is_pypy else ['python3']

def _spark_cmdenv(self, step_num):
    """Returns a dictionary mapping environment variable to value,
    including mapping PYSPARK_PYTHON to self._python_bin()
    """
    step = self._get_step(step_num)

    cmdenv = {}

    if self._step_type_uses_pyspark(step['type']):
        driver_python = cmd_line(self._python_bin())

        if self._spark_python_wrapper_path:
            executor_python = './%s' % self._working_dir_mgr.name(
                'file', self._spark_python_wrapper_path)
        else:
            executor_python = cmd_line(self._task_python_bin())

        if self._spark_deploy_mode() == 'cluster':
            # treat driver like executors (they run in same environment)
            cmdenv['PYSPARK_PYTHON'] = executor_python
        elif driver_python == executor_python:
            # no difference, just set $PYSPARK_PYTHON
            cmdenv['PYSPARK_PYTHON'] = driver_python
        else:
            # set different pythons for driver and executor
            cmdenv['PYSPARK_PYTHON'] = executor_python
            cmdenv['PYSPARK_DRIVER_PYTHON'] = driver_python

    cmdenv.update(self._cmdenv())
    return cmdenv

def cmd_line(args):
    """build a command line that works in a shell.
    """
    args = [str(x) for x in args]
    return ' '.join(pipes.quote(x) for x in args)

def _default_opts(cls):
    try:
        owner = getpass.getuser()
    except:
        owner = None

    return dict(
        check_input_paths=True,
        cleanup=['ALL'],
        cleanup_on_failure=['NONE'],
        owner=owner,
    )

def parse_legacy_hash_path(type, path, must_name=None):
    """Parse hash paths from old setup/bootstrap options.

    This is similar to parsing hash paths out of shell commands (see
    :py:func:`parse_setup_cmd`) except that we pass in
    path type explicitly, and we don't always require the ``#`` character.

    :param type: Type of the path (``'archive'`` or ``'file'``)
    :param path: Path to parse, possibly with a ``#``
    :param must_name: If set, use *path*'s filename as its name if there
                      is no ``'#'`` in *path*, and raise an exception
                      if there is just a ``'#'`` with no name. Set *must_name*
                      to the name of the relevant option so we can print
                      a useful error message. This is intended for options
                      like ``upload_files`` that merely upload a file
                      without tracking it.
    """
    if type not in _SUPPORTED_TYPES:
        raise ValueError('bad path type %r, must be one of %s' % (
            type, ', '.join(sorted(_SUPPORTED_TYPES))))

    if '#' in path:
        path, name = path.split('#', 1)

        # allow a slash after the name of an archive or dir because that's
        # the new-way of specifying archive paths
        if type in ('archive', 'dir'):
            name = name.rstrip('/' + os.sep)

        if '/' in name or '#' in name:
            raise ValueError(
                'Bad path %r; name must not contain # or /' % (path,))
    else:
        if must_name:
            if type == 'dir':
                # handle trailing slash on directory names
                name = os.path.basename(path.rstrip('/' + os.sep))
            else:
                name = os.path.basename(path)
        else:
            name = None

    if not path:
        raise ValueError('Path may not be empty!')

    if not name:
        if must_name:
            raise ValueError(
                'Empty name makes no sense for %s: %r' % (must_name, path))
        else:
            name = None

    return {'path': path, 'name': name, 'type': type}

def _upload_local_files(self):
    self._copy_files_to_wd_mirror()

    if self._upload_mgr:
        self.fs.mkdir(self._upload_mgr.prefix)

        log.info('Copying other local files to %s' %
                 self._upload_mgr.prefix)
        for src_path, uri in self._upload_mgr.path_to_uri().items():
            log.debug('  %s -> %s' % (src_path, uri))
            self.fs.put(src_path, uri)

def path_to_uri(self):
    """Get a map from path to URI for all paths that were added,
    so we can figure out which files we need to upload."""
    return dict((path, self.uri(path))
                for path in self._path_to_name)

def _run(self):
    """Run the job."""
    raise NotImplementedError

def _get_input_paths(self):
    """Get the paths to input files, dumping STDIN to a local
    file if need be."""
    if self._input_manifest_path:
        return [self._input_manifest_path]

    if '-' in self._input_paths:
        if self._stdin_path is None:
            # prompt user, so they don't think the process has stalled
            log.info('reading from STDIN')

            stdin_path = os.path.join(self._get_local_tmp_dir(), 'STDIN')
            log.debug('dumping stdin to local file %s' % stdin_path)
            with open(stdin_path, 'wb') as stdin_file:
                for line in self._stdin:
                    # catch missing newlines (often happens with test data)
                    if not line.endswith(b'\n'):
                        line += b'\n'
                    stdin_file.write(line)

            self._stdin_path = stdin_path

    return [self._stdin_path if p == '-' else p for p in self._input_paths]

def _create_input_manifest_if_needed(self):
    """Create a file with a list of URIs of input files."""
    if self._input_manifest_path or not self._uses_input_manifest():
        return

    uris = []

    log.info('finding input files to add to manifest...')

    for path in self._get_input_paths():
        log.debug('  in %s' % path)
        if is_uri(path):
            # URIs might be globs
            for uri in self.fs.ls(path):
                uris.append(uri)
        else:
            # local paths are expected to be single files
            # (shell would resolve globs)
            if self._upload_mgr:
                uris.append(self._upload_mgr.uri(path))
            else:
                # just make sure job can find files from its working dir
                uris.append(os.path.abspath(path))

    log.info('found %d input files' % len(uris))

    path = os.path.join(self._get_local_tmp_dir(), 'input-manifest.txt')
    self._write_script(uris, path, 'input manifest')

    self._input_manifest_path = path
    if self._upload_mgr:
        self._upload_mgr.add(self._input_manifest_path)

def _add_input_files_for_upload(self):
    """If there is an upload manager, add input files to it."""
    if self._upload_mgr:
        for path in self._get_input_paths():
            self._upload_mgr.add(path)

def cat_output(self):
    """Stream the job's output, as a stream of ``bytes``. If there are
    multiple output files, there will be an empty bytestring
    (``b''``) between them.

    Like Hadoop input formats, we ignore files and subdirectories whose
    names start with ``"_"`` or ``"."`` (e.g. ``_SUCCESS``, ``_logs/``,
    ``.part-00000.crc``.

    .. versionchanged:: 0.6.8

       Ignore file/dirnames starting with ``"."`` as well as ``"_"``.
    """
    output_dir = self.get_output_dir()
    if output_dir is None:
        raise ValueError('Run the job before streaming output')

    if self._closed is True:
        log.warning(
            'WARNING! Trying to stream output from a closed runner, output'
            ' will probably be empty.')

    log.info('Streaming final output from %s...' % output_dir)

    def split_path(path):
        while True:
            base, name = os.path.split(path)

            # no more elements
            if not name:
                break

            yield name

            path = base

    def ls_output():
        for filename in self.fs.ls(output_dir):
            subpath = filename[len(output_dir):]
            # Hadoop ignores files and dirs inside the output dir
            # whose names start with '_' or '.'. See #1337.
            if not (any(name[0] in '_.'
                        for name in split_path(subpath))):
                yield filename

    for i, filename in enumerate(ls_output()):
        if i > 0:
            yield b''  # EOF of previous file

        for chunk in self.fs._cat_file(filename):
            yield chunk

def get_output_dir(self):
    """Find the directory containing the job output. If the job hasn't
    run yet, returns None"""
    if self._script_path and not self._ran_job:
        return None

    return self._output_dir

def split_path(path):
    while True:
        base, name = os.path.split(path)

        # no more elements
        if not name:
            break

        yield name

        path = base

def ls_output():
    for filename in self.fs.ls(output_dir):
        subpath = filename[len(output_dir):]
        # Hadoop ignores files and dirs inside the output dir
        # whose names start with '_' or '.'. See #1337.
        if not (any(name[0] in '_.'
                    for name in split_path(subpath))):
            yield filename

def _should_cat_output(self):
    if self.options.cat_output is None:
        return not self.options.output_dir
    else:
        return self.options.cat_output

def _cleanup_cluster(self):
    """Terminate the cluster if there is one."""
    pass  # this only happens on EMR

def __enter__(self):
    """Don't do anything special at start of with block"""
    return self

def __init__(self, archive_file_suffix=''):
    # map from paths added without a name to None or lazily chosen name
    self._typed_path_to_auto_name = {}
    self._name_to_typed_path = {}
    self._archive_file_suffix = archive_file_suffix

def get_opts(self):
    """Get options set for this runner, as a dict."""
    log.warning('get_opts() is deprecated and will be removed in v0.7.0')
    return copy.deepcopy(self._opts)

def _kwargs_from_switches(self, keys):
    return dict(
        (key, getattr(self.options, key))
        for key in keys if hasattr(self.options, key)
    )

def _runner_class(self):
    """Runner class as indicated by ``--runner``. Defaults to ``'inline'``.
    """
    return _runner_class(self.options.runner or 'inline')

def _create_dir_archives(self):
    """Call this to create all dir archives"""
    for dir_path in sorted(set(self._dir_to_archive_path)):
        self._create_dir_archive(dir_path)

def mkdir(self, path):
    path = _from_file_uri(path)
    if not os.path.isdir(path):
        os.makedirs(path)

def _label(self):
    """Return *label* opt, or if not set, the name of the file
    containing the MRJob, minus extension, or if none, ``'no_script'``"""
    if self._opts['label']:
        return self._opts['label']
    elif self._script_path:
        return os.path.basename(self._script_path).split('.')[0]
    else:
        return 'no_script'

def _owner(self):
    """Return *owner* opt (which defaults to :py:func:`getpass.getuser`),
    or ``'no_user'`` if not set."""
    if self._opts['owner']:
        # owner opt defaults to getpass.getuser()
        return self._opts['owner']
    else:
        return 'no_user'

def _has_spark_steps(self):
    """Are any of our steps Spark steps? (e.g. spark, spark_jar,
    spark_script)

    Generally used to determine if we need to install Spark on a cluster.
    """
    return any(self._step_type_uses_spark(step['type'])
               for step in self._get_steps())

def _wd_mirror(self):
    """A directory to upload files belonging to
    :py:attr:`_working_dir_mgr`. This will be a subdir of
    ``self._upload_mgr.prefix`, if it exists, and otherwise will
    be ``None``."""
    if self._upload_mgr and is_uri(self._upload_mgr.prefix):
        return posixpath.join(self._upload_mgr.prefix, 'wd')
    elif (self._has_spark_steps() and self._spark_executors_have_own_wd()):
        return os.path.join(self._get_local_tmp_dir(), 'wd-mirror')
    else:
        return None

def _has_pyspark_steps(self):
    """Do any of our steps involve running Python on Spark?
    Includes spark and spark_script types, but not spark_jar.

    Generally used to tell if we need a Spark setup script.
    """
    return any(self._step_type_uses_pyspark(step['type'])
               for step in self._get_steps())

def _step_type_uses_pyspark(self, step_type):
    """Does this step involve running Python on Spark?

    (This is re-defined in the Spark runner to include
    streaming steps, and used by mrjob.logs.mixin)
    """
    return _is_pyspark_step_type(step_type)

def _is_pyspark_step_type(step_type):
    """Does the given step type indicate that it uses Spark and Python?"""
    return step_type in ('spark', 'spark_script')

def _check_step(self, step, step_num):
    """Don't try to run steps that include commands or use manifests."""
    super(SparkMRJobRunner, self)._check_step(step, step_num)

    if step.get('input_manifest'):
        raise NotImplementedError(
            'spark runner does not support input manifests')

    # we don't currently support commands, but we *could* (see #1956).
    if step['type'] == 'streaming':
        if not self._mrjob_cls:
            raise ValueError(
                'You must set mrjob_cls to run streaming steps')

        for mrc in ('mapper', 'combiner', 'reducer'):
            if step.get(mrc):
                if 'command' in step[mrc] or 'pre_filter' in step[mrc]:
                    raise NotImplementedError(
                        "step %d's %s runs a command, but spark"
                        " runner does not support commands" % (
                            step_num, mrc))

def _has_hadoop_streaming_steps(self):
    # the Spark runner doesn't run "streaming" steps on Hadoop
    return False

def _step_type_uses_pyspark(self, step_type):
    """Treat streaming steps as Spark steps that use Python."""
    return (
        super(SparkMRJobRunner, self)._step_type_uses_pyspark(step_type) or
        step_type == 'streaming')

def _step_type_uses_spark(self, step_type):
    """Treat streaming steps as Spark steps that use Python."""
    return (
        super(SparkMRJobRunner, self)._step_type_uses_spark(step_type) or
        step_type == 'streaming')

def _spark_script_args(self, step_num, last_step_num=None):
    """A list of args to the spark script/jar/MRJob, used by
    _args_for_spark_step().

    *last_step_num* is only used by the Spark runner, where multiple
    streaming steps are run in a single Spark job."""
    step = self._get_step(step_num)

    if step['type'] == 'spark':
        # if on local[*] master, keep file upload args as-is (see #2031)
        local = not self._spark_executors_have_own_wd()

        args = (
            [
                '--step-num=%d' % step_num,
                '--spark',
            ] + self._mr_job_extra_args(local=local) + [
                INPUT,
                OUTPUT,
            ]
        )
    elif step['type'] in ('spark_jar', 'spark_script'):
        args = step['args']
    else:
        raise TypeError('Bad step type: %r' % step['type'])

    return self._interpolate_step_args(args, step_num)

def get_spark_submit_bin(self):
    """Return the location of the ``spark-submit`` binary, searching for it
    if necessary."""
    if not self._spark_submit_bin:
        self._spark_submit_bin = self._find_spark_submit_bin()
    return self._spark_submit_bin

def _spark_upload_args(self):
    if not self._spark_executors_have_own_wd():
        # don't bother, there's no working dir to upload to
        return []

    return self._upload_args_helper(
        '--files', None,
        '--archives', None,
        always_use_hash=False,
        emulate_archives=self._emulate_archives_on_spark())

def _spark_script_path(self, step_num):
    """The path of the spark script or JAR, used by
    _args_for_spark_step()."""
    step = self._get_step(step_num)

    if step['type'] == 'spark':
        path = self._script_path
    elif step['type'] == 'spark_jar':
        path = step['jar']
    elif step['type'] == 'spark_script':
        path = step['script']
    else:
        raise TypeError('Bad step type: %r' % step['type'])

    return self._interpolate_spark_script_path(path)

def _args_for_task(self, step_num, mrc):
    return [
        '--step-num=%d' % step_num,
        '--%s' % mrc,
    ] + self._mr_job_extra_args()

def _mr_job_extra_args(self, local=False):
    """Return arguments to add to every invocation of MRJob.

    :type local: boolean
    :param local: if this is True, use files' local paths rather than
        the path they'll have inside Hadoop streaming
    """
    result = []

    for extra_arg in self._extra_args:
        if isinstance(extra_arg, dict):
            if local:
                result.append(extra_arg['path'])
            else:
                result.append(self._working_dir_mgr.name(**extra_arg))
        else:
            result.append(extra_arg)

    return result

def _script_args_for_step(self, step_num, mrc, input_manifest=False):
    args = (self._task_python_bin() +
            [self._working_dir_mgr.name('file', self._script_path)] +
            self._args_for_task(step_num, mrc))

    if input_manifest and mrc == 'mapper':
        wrapper = self._manifest_setup_script_path
    elif self._setup_wrapper_script_path:
        wrapper = self._setup_wrapper_script_path
    else:
        return args

    return (self._sh_bin() + [
        self._working_dir_mgr.name('file', wrapper)] + args)

def _substep_args(self, step_num, mrc):
    step = self._get_step(step_num)

    if step[mrc]['type'] == 'command':
        cmd = step[mrc]['command']

        # never wrap custom hadoop streaming commands in bash
        if isinstance(cmd, string_types):
            return shlex_split(cmd)
        else:
            return cmd

    elif step[mrc]['type'] == 'script':
        script_args = self._script_args_for_step(
            step_num, mrc, input_manifest=step.get('input_manifest'))

        if 'pre_filter' in step[mrc]:
            return self._sh_wrap(
                '%s | %s' % (step[mrc]['pre_filter'],
                             cmd_line(script_args)))
        else:
            return script_args
    else:
        raise ValueError("Invalid %s step %d: %r" % (
            mrc, step_num, step[mrc]))

def shlex_split(s):
    """Wrapper around shlex.split(), but convert to str if Python version <
    2.7.3 when unicode support was added.
    """
    if sys.version_info < (2, 7, 3):
        return shlex.split(str(s))
    else:
        return shlex.split(s)

def _interpolate_step_args(self, args, step_num):
    """Replace :py:data:`~mrjob.step.INPUT` and
    :py:data:`~mrjob.step.OUTPUT` in arguments to a jar or Spark
    step.
    """
    result = []

    for arg in args:
        if arg == INPUT:
            result.append(
                ','.join(self._step_input_uris(step_num)))

        elif arg == OUTPUT:
            result.append(
                self._step_output_uri(step_num))

        else:
            result.append(arg)

    return result

def _step_input_uris(self, step_num):
    """A list of URIs to use as input for the given step. For all
    except the first step, this list will have a single item (a
    directory)."""
    if step_num == 0:
        return [self._upload_mgr.uri(path) if self._upload_mgr
                else to_uri(path)
                for path in self._get_input_paths()]
    else:
        return [to_uri(self._intermediate_output_dir(step_num - 1))]

def _step_output_uri(self, step_num):
    """URI to use as output for the given step. This is either an
    intermediate dir (see :py:meth:`intermediate_output_uri`) or
    ``self._output_dir`` for the final step."""
    if step_num == len(self._get_steps()) - 1:
        return to_uri(self._output_dir)
    else:
        return to_uri(self._intermediate_output_dir(step_num))

def to_uri(path_or_uri):
    """If *path_or_uri* is not a URI already, convert it to a ``file:///``
    URI."""
    if is_uri(path_or_uri):
        return path_or_uri
    else:
        return urljoin('file:', pathname2url(abspath(path_or_uri)))

def _bootstrap_mrjob(self):
    """Should we bootstrap mrjob?"""
    if self._opts['bootstrap_mrjob'] is None:
        return True
    else:
        return bool(self._opts['bootstrap_mrjob'])

def _py_files_setup(self):
    """A list of additional setup commands to emulate Spark's
    --py-files option on Hadoop Streaming."""
    result = []

    for py_file in self._py_files():
        path_dict = {'type': 'file', 'name': None, 'path': py_file}
        self._working_dir_mgr.add(**path_dict)
        result.append(['export PYTHONPATH=', path_dict, ':$PYTHONPATH'])

    return result

def _check_input_paths(self):
    """Check that input exists prior to running the job, if the
    `check_input_paths` option is true."""
    if not self._opts['check_input_paths']:
        return

    for path in self._input_paths:
        self._check_input_path(path)

def _check_input_path(self, path):
    """Raise :py:class:`IOError` if the given input does not exist or
    is otherwise invalid. Override this to provide custom check
    behavior."""
    if path == '-':
        return  # STDIN always exists

    if not self.fs.can_handle_path(path):
        return  # no way to check (e.g. non-S3 URIs on EMR)

    if not self.fs.exists(path):
        raise IOError(
            'Input path %s does not exist!' % (path,))

def _upload_args(self):
    # just upload every file and archive in the working dir manager
    return self._upload_args_helper('-files', None, '-archives', None)

def _file_arg_hash_paths(self, named_paths=None, always_use_hash=True):
    """Helper function for the *upload_args methods. The names of all
    arguments to ``-files`` (or ``--files`` on Spark).

    If *always_use_hash* is false, only use ``path#name`` syntax
    when the name is different.
    """
    if named_paths is None:
        # just return every file managed by _working_dir_mgr
        named_paths = sorted(
            self._working_dir_mgr.name_to_path('file').items())

    for name, path in named_paths:
        if not name:
            name = self._working_dir_mgr.name('file', path)

        uri = self._dest_in_wd_mirror(path, name) or path

        if not always_use_hash and _basename(uri) == name:
            yield uri
        else:
            yield '%s#%s' % (uri, name)

def name_to_path(self, type=None):
    """Get a map from name (in the setup directory) to path for
    all known files/archives, so we can build :option:`-file` and
    :option:`-archive` options to Hadoop (or fake them in a bootstrap
    script).

    :param type: either ``'archive'`` or ``'file'``
    """
    if type is not None:
        self._check_type(type)

    for path_type, path in self._typed_path_to_auto_name:
        if type is None or path_type == type:
            self.name(path_type, path)

    return dict((name, typed_path[1])
                for name, typed_path
                in self._name_to_typed_path.items()
                if (type is None or typed_path[0] == type))

def _write_script_lines(self, lines, path):
    """Write text to the given file. By default, this writes
    binary data, but can be redefined to use local line endings."""
    with open(path, 'wb') as f:
        for line in lines:
            f.write((line + '\n').encode('utf-8'))

def _fix_env(env):
    """Convert environment dictionary to strings (Python 2.7 on Windows
    doesn't allow unicode)."""
    def _to_str(s):
        if isinstance(s, string_types) and not isinstance(s, str):
            return s.encode('utf_8')
        else:
            return s

    return dict((_to_str(k), _to_str(v)) for k, v in env.items())

def _to_str(s):
    if isinstance(s, string_types) and not isinstance(s, str):
        return s.encode('utf_8')
    else:
        return s

def combine_lists(*seqs):
    """Concatenate the given sequences into a list. Ignore ``None`` values.

    Generally this is used for a list of commands we want to run; the
    "default" commands get run before any commands specific to your job.

    Strings, bytes, and non-sequence objects (e.g. numbers) are treated as
    single-item lists.
    """
    result = []

    for seq in seqs:
        if seq is None:
            continue

        if isinstance(seq, (bytes, string_types, dict)):
            result.append(seq)
        else:
            try:
                result.extend(seq)
            except:
                result.append(seq)

    return result

def _runner_class(alias):
    """Get the runner subclass corresponding to the given alias
    (importing code only as needed)."""
    if alias == 'dataproc':
        from mrjob.dataproc import DataprocJobRunner
        return DataprocJobRunner

    elif alias == 'emr':
        from mrjob.emr import EMRJobRunner
        return EMRJobRunner

    elif alias == 'hadoop':
        from mrjob.hadoop import HadoopJobRunner
        return HadoopJobRunner

    elif alias == 'inline':
        from mrjob.inline import InlineMRJobRunner
        return InlineMRJobRunner

    elif alias == 'local':
        from mrjob.local import LocalMRJobRunner
        return LocalMRJobRunner

    elif alias == 'spark':
        from mrjob.spark.runner import SparkMRJobRunner
        return SparkMRJobRunner

    else:
        raise ValueError('bad runner alias: %s' % alias)

def _spark_submit(args):
    from mrjob.tools.spark_submit import main
    main(args)

def _get_runner_opt_kwargs(options, runner_class):
    """Extract the options for the given runner class from *options*."""
    return {opt_name: getattr(options, opt_name)
            for opt_name in runner_class.OPT_NAMES
            if hasattr(options, opt_name)}

def _get_step(options, parser, cl_args):
    """Extract the step from the runner options."""
    args = options.args
    main_class = options.main_class
    spark_args = _get_spark_args(parser, cl_args)
    script_or_jar = options.script_or_jar

    if script_or_jar.lower().endswith('.jar'):
        return SparkJarStep(args=args,
                            jar=script_or_jar,
                            main_class=main_class,
                            spark_args=spark_args)
    elif script_or_jar.lower().split('.')[-1].startswith('py'):
        return SparkScriptStep(args=args,
                               script=script_or_jar,
                               spark_args=spark_args)
    else:
        raise ValueError('%s appears not to be a JAR or Python script' %
                         options.script_or_jar)

def du(self, path_glob):
    """Get the size of a file or directory (recursively), or 0
    if it doesn't exist."""
    try:
        stdout = self.invoke_hadoop(['fs', '-du', path_glob],
                                    return_stdout=True,
                                    ok_returncodes=[0, 1, 255])
    except CalledProcessError:
        return 0

    try:
        return sum(int(line.split()[0])
                   for line in stdout.split(b'\n')
                   if line.strip())
    except (ValueError, TypeError, IndexError):
        raise IOError(
            'Unexpected output from hadoop fs -du: %r' % stdout)

def _dict_list_to_compat_map(dict_list):
    # compat_map = {
    #   ...
    #   a: {'1.0': a, '2.0': b}
    #   ..
    # }
    compat_map = {}
    for version_dict in dict_list:
        for value in version_dict.values():
            compat_map[value] = version_dict
    return compat_map

def _emr_proof_steps_desc(steps_desc):
    # EMR's command-runner.jar does some very strange things to
    # arguments, including deleting empty args and deleting
    # '}}' from arguments. See #2070
    return _CLOSE_BRACE_AFTER_CLOSE_BRACE_RE.sub(' }', steps_desc)

def to_unicode(s):
    """Convert ``bytes`` to unicode.

    Use this if you need to ``print()`` or log bytes of an unknown encoding,
    or to parse strings out of bytes of unknown encoding (e.g. a log file).

    This hopes that your bytes are UTF-8 decodable, but if not, falls back
    to latin-1, which always works.
    """
    if isinstance(s, bytes):
        try:
            return s.decode('utf_8')
        except UnicodeDecodeError:
            return s.decode('latin_1')
    elif isinstance(s, string_types):  # e.g. is unicode
        return s
    else:
        raise TypeError

def get_hadoop_version(self):
    """Invoke the hadoop executable to determine its version"""
    # mkdir() needs this
    if not self._hadoop_version:
        stdout = self.invoke_hadoop(['version'], return_stdout=True)
        if stdout:
            first_line = stdout.split(b'\n')[0]
            m = _HADOOP_VERSION_RE.match(first_line)
            if m:
                self._hadoop_version = to_unicode(m.group('version'))
                log.info("Using Hadoop version %s" % self._hadoop_version)
            else:
                raise Exception('Unable to determine Hadoop version.')

    return self._hadoop_version

def mkdir(self, path):
    version = self.get_hadoop_version()

    # use -p on Hadoop 2 (see #991, #845)
    if uses_yarn(version):
        args = ['fs', '-mkdir', '-p', path]
    else:
        args = ['fs', '-mkdir', path]

    try:
        self.invoke_hadoop(args, ok_stderr=[_HADOOP_FILE_EXISTS_RE])
    except CalledProcessError:
        raise IOError("Could not mkdir %s" % path)

def put(self, src, path):
    # don't inadvertently support cp syntax
    if path.endswith('/'):
        raise ValueError('put() destination may not be a directory')

    self.invoke_hadoop(['fs', '-put', src, path])

def rm(self, path_glob):
    if not is_uri(path_glob):
        super(HadoopFilesystem, self).rm(path_glob)

    version = self.get_hadoop_version()
    if uses_yarn(version):
        args = ['fs', '-rm', '-R', '-f', '-skipTrash', path_glob]
    else:
        args = ['fs', '-rmr', '-skipTrash', path_glob]

    try:
        self.invoke_hadoop(
            args,
            return_stdout=True, ok_stderr=[_HADOOP_RM_NO_SUCH_FILE])
    except CalledProcessError:
        raise IOError("Could not rm %s" % path_glob)

def version_gte(version, cmp_version_str):
    """Return ``True`` if version >= *cmp_version_str*."""

    if not isinstance(version, string_types):
        raise TypeError('%r is not a string' % version)

    if not isinstance(cmp_version_str, string_types):
        raise TypeError('%r is not a string' % cmp_version_str)

    return LooseVersion(version) >= LooseVersion(cmp_version_str)

def _find_spark_submit_bin(self):
    if version_gte(self.get_image_version(), '4'):
        return ['spark-submit']
    else:
        return [_3_X_SPARK_SUBMIT]

def _spark_jar(self):
    if version_gte(self.get_image_version(), '4'):
        return _4_X_COMMAND_RUNNER_JAR
    else:
        return self._script_runner_jar_uri()

def _get_streaming_jar_and_step_arg_prefix(self):
    if self._opts['hadoop_streaming_jar']:
        if self._opts['hadoop_streaming_jar'].startswith('file://'):
            # special case: jar is already on EMR
            # relative paths are OK (though maybe not useful)
            return self._opts['hadoop_streaming_jar'][7:], []
        else:
            return self._upload_mgr.uri(
                self._opts['hadoop_streaming_jar']), []
    elif version_gte(self.get_image_version(), '4'):
        # 4.x AMIs use an intermediary jar
        return _4_X_COMMAND_RUNNER_JAR, ['hadoop-streaming']
    else:
        # 2.x and 3.x AMIs just use a regular old streaming jar
        return _PRE_4_X_STREAMING_JAR, []

def get_image_version(self):
    """Get the version of the AMI that our cluster is running, or ``None``.
    """
    return self._get_cluster_info('image_version')

def _expanded_mrjob_conf_path(conf_path=None):
    """Return the path of a single conf file. If *conf_path* is ``False``,
    return ``None``, and if it's ``None``, return :py:func:`find_mrjob_conf`.
    Otherwise, expand environment variables and ``~`` in *conf_path* and
    return it.

    Confusingly, this function doesn't actually return a "real" path according
    to ``os.path.realpath()``; it just resolves environment variables and
    ``~``.
    """
    if conf_path is False:
        return None
    elif conf_path is None:
        return find_mrjob_conf()
    else:
        return expand_path(conf_path)

def _load_opts_from_mrjob_conf(runner_alias, conf_path, already_loaded):
    """Helper for :py:func:`load_opts_from_mrjob_conf` for recursive use.
    This doesn't expand or default *conf_path*.
    """
    conf = _conf_object_at_path(conf_path)

    if conf is None:
        return [(None, {})]

    # don't load same conf file twice
    real_conf_path = os.path.realpath(conf_path)

    if real_conf_path in already_loaded:
        return []
    else:
        already_loaded.append(real_conf_path)

    # get configs for our runner out of conf file
    try:
        values = conf['runners'][runner_alias] or {}
    except (KeyError, TypeError, ValueError):
        values = {}

    inherited = []
    if conf.get('include', None):
        includes = conf['include']
        if isinstance(includes, string_types):
            includes = [includes]

        # handle includes in reverse order so that include order takes
        # precedence over inheritance
        for include in reversed(includes):
            # make include relative to (real) conf_path (see #1166)
            # expand ~ *before* joining to dir of including file (see #1308)
            include = os.path.join(os.path.dirname(real_conf_path),
                                   expand_path(include))

            inherited = _load_opts_from_mrjob_conf(
                runner_alias, include, already_loaded) + inherited

    return inherited + [(conf_path, values)]

def expand_path(path):
    """Resolve ``~`` (home dir) and environment variables in *path*.

    If *path* is ``None``, return ``None``.
    """
    if path is None:
        return None
    else:
        return os.path.expanduser(os.path.expandvars(path))

def __eq__(self, other):
    if isinstance(other, ClearedValue):
        return self.value == other.value
    else:
        return False

def __eq__(self, other):
    return (isinstance(other, self.__class__) and
            all(getattr(self, key) == getattr(other, key)
                for key in set(self._STEP_ATTRS)))

def addInPlace(self, value1, value2):
    for group in value2:
        for key in value2[group]:
            if key not in value1[group]:
                value1[group][key] = value2[group][key]
            else:
                value1[group][key] += value2[group][key]
    return value1

def __repr__(self):
    return '%s(%s)' % (
        self.__class__.__name__,
        ', '.join(('%s=%r' % (k, getattr(self, k))
                   for k in self._FIELDS
                   if getattr(self, k) is not None)))

def __repr__(self):
    not_none = dict((k, v) for k, v in self._steps.items()
                    if v is not None)
    return '%s(%s)' % (
        self.__class__.__name__,
        ', '.join('%s=%r' % (k, v) for k, v in not_none.items()))

def _cleared_value_constructor(loader, node):
    # tried construct_object(), got an unconstructable recursive node warning
    if isinstance(node, yaml.MappingNode):
        value = loader.construct_mapping(node)
    elif isinstance(node, yaml.ScalarNode):
        # resolve null as None, not u'null'
        value = yaml.safe_load(node.value)
    elif isinstance(node, yaml.SequenceNode):
        value = loader.construct_sequence(node)
    else:
        raise TypeError

    return ClearedValue(value)

def _load_yaml_with_clear_tag(stream):
    """Like yaml.safe_load(), but everything with a !clear tag before it
    will be wrapped in ClearedValue()."""
    loader = yaml.SafeLoader(stream)
    loader.add_constructor('!clear', _cleared_value_constructor)
    try:
        return loader.get_single_data()
    finally:
        if hasattr(loader, 'dispose'):  # it doesn't in PyYAML 3.09
            loader.dispose()

def _fix_clear_tags(x):
    """Recursively resolve :py:class:`ClearedValue` wrappers so that
    ``ClearedValue(...)`` can only wrap values in dicts (and in the top-level
    value we return).

    In dicts, we treat ``ClearedValue(k): v`` or
    ``ClearedValue(k): ClearedValue(v)`` as equivalent to
    ``k: ClearedValue(v)``. ``ClearedValue(k): v1`` overrides ``k: v2``.

    In lists, any ClearedValue wrappers are simply stripped.
    """
    _fix = _fix_clear_tags

    if isinstance(x, list):
        return [_fix(_strip_clear_tag(item)) for item in x]

    elif isinstance(x, dict):
        d = dict((_fix(k), _fix(v)) for k, v in x.items())

        # handle cleared keys
        for k, v in list(d.items()):
            if isinstance(k, ClearedValue):
                del d[k]
                d[_strip_clear_tag(k)] = ClearedValue(_strip_clear_tag(v))

        return d

    elif isinstance(x, ClearedValue):
        return ClearedValue(_fix(x.value))

    else:
        return x

def _strip_clear_tag(v):
    """remove the clear tag from the given value."""
    if isinstance(v, ClearedValue):
        return v.value
    else:
        return v

def _conf_object_at_path(conf_path):
    if conf_path is None:
        return None

    with open(conf_path) as f:
        if yaml:
            return _fix_clear_tags(_load_yaml_with_clear_tag(f))
        else:
            try:
                return json.load(f)
            except ValueError as e:
                raise ValueError(
                    'Could not read JSON from %s\n  %s\n\n'
                    'If your conf file is in YAML, you need to'
                    ' `pip install PyYAML` to read it' % (conf_path, str(e)))

def _cleared_value_representer(dumper, data):
    if not isinstance(data, ClearedValue):
        raise TypeError
    node = dumper.represent_data(data.value)
    node.tag = '!clear'
    return node

def _dump_yaml_with_clear_tags(data, stream=None, **kwds):
    class ClearedValueSafeDumper(yaml.SafeDumper):
        pass

    ClearedValueSafeDumper.add_representer(
        ClearedValue, _cleared_value_representer)

    return yaml.dump_all([data], stream, Dumper=ClearedValueSafeDumper, **kwds)

def dump_mrjob_conf(conf, f):
    """Write out configuration options to a file.

    Useful if you don't want to bother to figure out YAML.

    *conf* should look something like this:

        {'runners':
            'local': {'OPTION': VALUE, ...}
            'emr': {'OPTION': VALUE, ...}
            'hadoop: {'OPTION': VALUE, ...}
        }

    :param f: a file object to write to (e.g. ``open('mrjob.conf', 'w')``)
    """
    if yaml:
        _dump_yaml_with_clear_tags(conf, f, default_flow_style=False)
    else:
        json.dump(conf, f, indent=2)
    f.flush()

def combine_values(*values):
    """Return the last value in *values* that is not ``None``.

    The default combiner; good for simple values (booleans, strings, numbers).
    """
    for v in reversed(values):
        if v is not None:
            return v
    else:
        return None

def combine_cmds(*cmds):
    """Take zero or more commands to run on the command line, and return
    the last one that is not ``None``. Each command should either be a list
    containing the command plus switches, or a string, which will be parsed
    with :py:func:`shlex.split`. The string must either be a byte string or a
    unicode string containing no non-ASCII characters.

    Returns either ``None`` or a list containing the command plus arguments.
    """
    cmd = combine_values(*cmds)

    if cmd is None:
        return None
    elif isinstance(cmd, string_types):
        return shlex_split(cmd)
    else:
        return list(cmd)

def combine_paths(*paths):
    """Returns the last value in *paths* that is not ``None``.
    Resolve ``~`` (home dir) and environment variables."""
    return expand_path(combine_values(*paths))

def combine_jobconfs(*jobconfs):
    """Like combine_dicts(), but non-string values are converted to
    Java-readable string (e.g. True becomes 'true'). Keys whose
    value is None are blanked out."""
    j = combine_dicts(*jobconfs)

    return {k: _to_java_str(v) for k, v in j.items() if v is not None}

def _to_java_str(x):
    """Convert a value (usually for a configuration property) into its
    Java string representation, falling back to the Python representation
    if None is available."""
    # e.g. True -> 'true', None -> 'null'. See #323
    if isinstance(x, string_types):
        return x
    elif x is None:
        # Note: combine_jobconfs() blanks out keys with None values
        return 'null'
    elif isinstance(x, bool):
        return 'true' if x else 'false'
    else:
        return str(x)

def spark_args(self):
    """Redefine this to pass custom arguments to Spark."""
    return []

def _get_step(self, step_num, expected_type):
    """Helper for run_* methods"""
    steps = self.steps()
    if not 0 <= step_num < len(steps):
        raise ValueError('Out-of-range step: %d' % step_num)
    step = steps[step_num]
    if not isinstance(step, expected_type):
        raise TypeError('Step %d is not a %s', expected_type.__name__)
    return step

def _steps_desc(self):
    step_descs = []
    for step_num, step in enumerate(self.steps()):
        step_descs.append(step.description(step_num))
    return step_descs

def write_line(key, value):
    self.stdout.write(write(key, value))
    self.stdout.write(b'\n')

def exists(self, path_glob):
    # just fall back on ls(); it's smart
    try:
        return any(self.ls(path_glob))
    except IOError:
        return False

def mr_job_script(cls):
    """Path of this script. This returns the file containing
    this class, or ``None`` if there isn't any (e.g. it was
    defined from the command line interface.)"""
    try:
        return inspect.getsourcefile(cls)
    except TypeError:
        return None

def _render_substep(self, step_num, mrc):
    step = self._get_step(step_num)

    if mrc in step:
        # cmd_line() does things that shell is fine with but
        # Hadoop Streaming finds confusing.
        return _hadoop_cmd_line(self._substep_args(step_num, mrc))
    else:
        if mrc == 'mapper':
            return 'cat'
        else:
            return None

def _hadoop_streaming_commands(self, step_num):
    return (
        self._render_substep(step_num, 'mapper'),
        self._render_substep(step_num, 'combiner'),
        self._render_substep(step_num, 'reducer'),
    )

def _hadoop_cmd_line(args):
    """Escape args of a command line in a way that Hadoop can process
    them."""
    return ' '.join(_hadoop_escape_arg(arg) for arg in args)

def _hadoop_escape_arg(arg):
    """Escape a single command argument in a way that Hadoop can process it."""
    if _HADOOP_SAFE_ARG_RE.match(arg):
        return arg
    else:
        return "'%s'" % arg.replace("'", r"'\''")

def __init__(self, jar, main_class, **kwargs):
    super(SparkJarStep, self).__init__(
        jar=jar, main_class=main_class, **kwargs)

def execute(self):
    # MRJob does Hadoop Streaming stuff, or defers to its superclass
    # (MRJobLauncher) if not otherwise instructed
    if self.options.run_mapper:
        self.run_mapper(self.options.step_num)

    elif self.options.run_combiner:
        self.run_combiner(self.options.step_num)

    elif self.options.run_reducer:
        self.run_reducer(self.options.step_num)

    elif self.options.run_spark:
        self.run_spark(self.options.step_num)

    else:
        self.run_job()

def map_pairs(self, pairs, step_num=0):
    """Runs :py:meth:`mapper_init`,
    :py:meth:`mapper`/:py:meth:`mapper_raw`, and :py:meth:`mapper_final`
    for one map task in one step.

    Takes in a sequence of (key, value) pairs as input, and yields
    (key, value) pairs as output.

    :py:meth:`run_mapper` essentially wraps this method with code to handle
    reading/decoding input and writing/encoding output.

    .. versionadded:: 0.6.7
    """
    step = self._get_step(step_num, MRStep)

    mapper = step['mapper']
    mapper_raw = step['mapper_raw']
    mapper_init = step['mapper_init']
    mapper_final = step['mapper_final']

    if mapper_init:
        for k, v in mapper_init() or ():
            yield k, v

    if mapper_raw:
        if len(self.options.args) != 2:
            raise ValueError('Wrong number of args')
        input_path, input_uri = self.options.args
        for k, v in mapper_raw(input_path, input_uri) or ():
            yield k, v
    else:
        for key, value in pairs:
            for k, v in mapper(key, value) or ():
                yield k, v

    if mapper_final:
        for k, v in mapper_final() or ():
            yield k, v

def combiner_helper(pairs1, pairs2):
    if len(pairs1) == len(pairs2) == 1:
        return list(
            combiner_job.combine_pairs(pairs1 + pairs2, step_num),
        )
    else:
        pairs1.extend(pairs2)
        return pairs1

def _combine_or_reduce_pairs(self, pairs, mrc, step_num=0):
    """Helper for :py:meth:`combine_pairs` and :py:meth:`reduce_pairs`."""
    step = self._get_step(step_num, MRStep)

    task = step[mrc]
    task_init = step[mrc + '_init']
    task_final = step[mrc + '_final']
    if task is None:
        raise ValueError('No %s in step %d' % (mrc, step_num))

    if task_init:
        for k, v in task_init() or ():
            yield k, v

    # group all values of the same key together, and pass to the reducer
    #
    # be careful to use generators for everything, to allow for
    # very large groupings of values
    for key, pairs_for_key in itertools.groupby(pairs, lambda k_v: k_v[0]):
        values = (value for _, value in pairs_for_key)
        for k, v in task(key, values) or ():
            yield k, v

    if task_final:
        for k, v in task_final() or ():
            yield k, v

def _read_input(self):
    """Read from stdin, or one more files, or directories.
    Yield one line at time.

    - Resolve globs (``foo_*.gz``).
    - Decompress ``.gz`` and ``.bz2`` files.
    - If path is ``-``, read from STDIN.
    - Recursively read all files in a directory
    """
    paths = self.options.args or ['-']

    for path in paths:
        if path == '-':
            for line in self.stdin:
                yield line
        else:
            with open(path, 'rb') as f:
                for line in to_lines(decompress(f, path)):
                    yield line

def read_lines():
    for line in self._read_input():
        key, value = read(line.rstrip(b'\r\n'))
        yield key, value

def to_lines(chunks):
    """Take in data as a sequence of bytes, and yield it, one line at a time.

    Only breaks lines on ``\\n`` (not ``\\r``), and does not add
    a trailing newline.

    For efficiency, passes through anything with a ``readline()`` attribute.
    """
    # hopefully this is good enough for anything mrjob will encounter
    if hasattr(chunks, 'readline'):
        return chunks
    else:
        return _to_lines(chunks)

def _mapper_output_protocol(self, step_num, step_map):
    map_key = self._step_key(step_num, 'mapper')
    if map_key in step_map:
        if step_map[map_key] >= (len(step_map) - 1):
            return self.output_protocol()
        else:
            return self.internal_protocol()
    else:
        # mapper is not a script substep, so protocols don't apply at all
        return RawValueProtocol()

def input_protocol(self):
    """Instance of the protocol to use to convert input lines to Python
    objects. Default behavior is to return an instance of
    :py:attr:`INPUT_PROTOCOL`.
    """
    if not isinstance(self.INPUT_PROTOCOL, type):
        log.warning('INPUT_PROTOCOL should be a class, not %s' %
                    self.INPUT_PROTOCOL)
    return self.INPUT_PROTOCOL()

def internal_protocol(self):
    """Instance of the protocol to use to communicate between steps.
    Default behavior is to return an instance of
    :py:attr:`INTERNAL_PROTOCOL`.
    """
    if not isinstance(self.INTERNAL_PROTOCOL, type):
        log.warning('INTERNAL_PROTOCOL should be a class, not %s' %
                    self.INTERNAL_PROTOCOL)
    return self.INTERNAL_PROTOCOL()

def output_protocol(self):
    """Instance of the protocol to use to convert Python objects to output
    lines. Default behavior is to return an instance of
    :py:attr:`OUTPUT_PROTOCOL`.
    """
    if not isinstance(self.OUTPUT_PROTOCOL, type):
        log.warning('OUTPUT_PROTOCOL should be a class, not %s' %
                    self.OUTPUT_PROTOCOL)
    return self.OUTPUT_PROTOCOL()

def _text_file_with_path(sc, path):
    """Return an RDD that yields (path, line) for each line in the file.

    *path* must be a single path, not a comma-separated list of paths
    """
    from pyspark.sql import SparkSession
    from pyspark.sql import functions as F

    spark = SparkSession(sc)

    df = spark.read.text(path).select([
        F.input_file_name().alias('input_file_name'),
        F.col('value')
    ])

    return df.rdd.map(
        lambda row: (row.input_file_name,
                     (row.value if isinstance(row.value, bytes)
                      else row.value.encode('utf_8')))
    )

def make_increment_counter(step_num):
    counter_accumulator = counter_accumulators[step_num - start]

    def increment_counter(group, counter, amount=1):
        counter_accumulator.add({group: {counter: amount}})

    return increment_counter

def _interpolate_jar_step_args(self, args, step_num):
    """Like :py:meth:`_interpolate_step_args` except it
    also replaces `~mrjob.step.GENERIC_ARGS` with
    :py:meth:`_hadoop_generic_args_for_step`. This only
    makes sense for jar steps; Spark should raise an error
    if `~mrjob.step.GENERIC_ARGS` is encountered.
    """
    result = []

    for arg in args:
        if arg == mrjob.step.GENERIC_ARGS:
            result.extend(
                self._hadoop_generic_args_for_step(step_num))
        else:
            result.append(arg)

    return self._interpolate_step_args(result, step_num)

def _parse_spark_log(lines, record_callback=None):
    """Parse a Spark log, looking for errors and application_id"""
    def yield_records():
        for record in _parse_hadoop_log4j_records(lines):
            if record_callback:
                record_callback(record)
            yield record

    return _parse_spark_log_from_log4j_records(yield_records())

def _parse_spark_log_from_log4j_records(records):
    """Helper for _parse_spark_log()"""

    # make sure *records* is a generator
    records = iter(records)

    result = {}

    for record in records:
        message = record['message']

        m = _SUBMITTED_APPLICATION_RE.match(message)
        if m:
            # need this on YARN or we won't be able to find container logs
            result['application_id'] = m.group('application_id')
            continue

        if record['level'] in ('WARN', 'ERROR'):
            # only interested in multi-line warnings
            if record['level'] == 'WARN' and record['num_lines'] == 1:
                continue

            error = dict(
                spark_error=dict(
                    message=message,
                    start_line=record['start_line'],
                    num_lines=record['num_lines'],
                )
            )

            if not result.get('errors'):
                result['errors'] = []

            result['errors'].append(error)
            continue

    return result

def _eio_to_eof(pty_master):
    """Yield lines from a PTY, gracefully handling an ``IOError`` with
    ``errno == EIO`` as end-of-file."""
    try:
        for line in pty_master:
            yield line
    except IOError as e:
        # this is just the PTY's way of saying goodbye
        if e.errno == errno.EIO:
            return
        else:
            raise

def _client_error_code(ex):
    """Get the error code for the given ClientError"""
    return ex.response.get('Error', {}).get('Code', '')

def _is_retriable_client_error(ex):
    """Is the exception from a boto3 client retriable?"""
    if isinstance(ex, botocore.exceptions.ClientError):
        # these rarely get through in boto3
        code = _client_error_code(ex)
        # "Throttl" catches "Throttled" and "Throttling"
        if any(c in code for c in ('Throttl', 'RequestExpired', 'Timeout')):
            return True
        # spurious 505s thought to be part of an AWS load balancer issue
        return _client_error_status(ex) == 505
    # in Python 2.7, SSLError is a subclass of socket.error, so catch
    # SSLError first
    elif isinstance(ex, SSLError):
        # catch ssl.SSLError: ('The read operation timed out',). See #1827.
        # also catches 'The write operation timed out'
        return any(isinstance(arg, str) and 'timed out' in arg
                   for arg in ex.args)
    elif isinstance(ex, socket.error):
        return ex.args in ((104, 'Connection reset by peer'),
                           (110, 'Connection timed out'))
    else:
        return False

def touchz(self, path):
    """Make an empty file in the given location. Raises an error if
    a non-empty file already exists in that location."""
    key = self._get_s3_key(path)

    data = None
    try:
        data = key.get()
    except botocore.exceptions.ClientError as ex:
        # okay if key doesn't exist
        if _client_error_status(ex) != 404:
            raise

    if data and data['ContentLength'] != 0:
        raise OSError('Non-empty file %r already exists!' % (path,))

    key.put(Body=b'')

def _cleanup_cluster(self):
    if not self._cluster_id:
        # If we don't have a cluster, then we can't terminate it.
        return

    emr_client = self.make_emr_client()
    try:
        log.info("Attempting to terminate cluster")
        emr_client.terminate_job_flows(
            JobFlowIds=[self._cluster_id]
        )
    except Exception as e:
        # Something happened with boto3 and the user should know.
        log.exception(e)
        return
    log.info('Cluster %s successfully terminated' % self._cluster_id)

def _endpoint_url(host_or_uri):
    """If *host_or_uri* is non-empty and isn't a URI, prepend ``'https://'``.

    Otherwise, pass through as-is.
    """
    if not host_or_uri:
        return host_or_uri
    elif is_uri(host_or_uri):
        return host_or_uri
    else:
        return 'https://' + host_or_uri

def _boto3_now():
    """Get a ``datetime`` that's compatible with :py:mod:`boto3`.
    These are always UTC time, with time zone ``dateutil.tz.tzutc()``.
    """
    if tzutc is None:
        raise ImportError(
            'You must install dateutil to get boto3-compatible datetimes')

    return datetime.now(tzutc())

def _report_long_jobs(args):
    from mrjob.tools.emr.report_long_jobs import main
    main(args)

def _filter_clusters(cluster_summaries, emr_client, exclude_strings):
    """ Filter out clusters that have tags matching any specified in
    exclude_strings.
    :param cluster_summaries: a list of :py:mod:`boto3` cluster summary data
                              structures
    :param exclude_strings: A list of strings of the form TAG_KEY,TAG_VALUE
    """
    exclude_as_dicts = []
    for exclude_string in exclude_strings:
        exclude_key, exclude_value = exclude_string.split(',')
        exclude_as_dicts.append({'Key': exclude_key, 'Value': exclude_value})

    for cs in cluster_summaries:
        cluster_id = cs['Id']
        cluster_tags = emr_client.describe_cluster(
            ClusterId=cluster_id)['Cluster']['Tags']
        for cluster_tag in cluster_tags:
            if cluster_tag in exclude_as_dicts:
                break
        else:
            yield cs

def __init__(self, **kwargs):
    # limit which keyword args can be specified
    bad_kwargs = sorted(set(kwargs) - set(_JOB_STEP_PARAMS))
    if bad_kwargs:
        raise TypeError('MRStep() got an unexpected keyword argument %r' %
                        bad_kwargs[0])

    if not set(kwargs) & set(_JOB_STEP_FUNC_PARAMS):
        raise ValueError("Step has no mappers and no reducers")

    self.has_explicit_mapper = any(
        value for name, value in kwargs.items()
        if name in _MAPPER_FUNCS)

    self.has_explicit_combiner = any(
        value for name, value in kwargs.items()
        if name in _COMBINER_FUNCS)

    self.has_explicit_reducer = any(
        value for name, value in kwargs.items()
        if name in _REDUCER_FUNCS)

    steps = dict((f, None) for f in _JOB_STEP_PARAMS)

    steps.update(kwargs)

    def _check_conflict(func, other_funcs):
        if steps[func]:
            for other_func in other_funcs:
                if steps[other_func] and other_func != func:
                    raise ValueError("Can't specify both %s and %s" % (
                        func, other_func))

    _check_conflict('mapper_cmd', _MAPPER_FUNCS)
    _check_conflict('mapper_raw', ('mapper', 'mapper_pre_filter'))
    _check_conflict('combiner_cmd', _COMBINER_FUNCS)
    _check_conflict('reducer_cmd', _REDUCER_FUNCS)

    self._steps = steps

def _check_conflict(func, other_funcs):
    if steps[func]:
        for other_func in other_funcs:
            if steps[other_func] and other_func != func:
                raise ValueError("Can't specify both %s and %s" % (
                    func, other_func))

def _render_substep(self, cmd_key, pre_filter_key):
    if self._steps[cmd_key]:
        cmd = self._steps[cmd_key]
        if not isinstance(cmd, string_types):
            cmd = cmd_line(cmd)
        if (pre_filter_key and self._steps[pre_filter_key]):
            raise ValueError('Cannot specify both %s and %s' % (
                cmd_key, pre_filter_key))
        return {'type': 'command', 'command': cmd}
    else:
        substep = {'type': 'script'}
        if (pre_filter_key and
                self._steps[pre_filter_key]):
            substep['pre_filter'] = self._steps[pre_filter_key]
        return substep

def description(self, step_num=0):
    desc = {'type': 'streaming'}
    # Use a mapper if:
    #   - the user writes one
    #   - it is the first step and we don't want to mess up protocols
    #   - there are only combiners and we don't want to mess up protocols
    if (step_num == 0 or
            self.has_explicit_mapper or
            self.has_explicit_combiner):
        desc['mapper'] = self.render_mapper()
    if self.has_explicit_combiner:
        desc['combiner'] = self.render_combiner()
    if self.has_explicit_reducer:
        desc['reducer'] = self.render_reducer()
    if self._steps['mapper_raw']:
        desc['input_manifest'] = True
    # TODO: verify this is a dict, convert booleans to strings
    if self._steps['jobconf']:
        desc['jobconf'] = self._steps['jobconf']

    return desc

def __init__(self, **kwargs):
    """Set all attributes to the corresponding value in *kwargs*, or the
    default value. Raise :py:class:`TypeError` for unknown arguments or
    values with the wrong type."""
    bad_kwargs = sorted(set(kwargs) - set(self._STEP_ATTRS))
    if bad_kwargs:
        raise TypeError('%s() got unexpected keyword arguments: %s' % (
            self.__class__.__name__, ', '.join(bad_kwargs)))

    for k in self._STEP_ATTRS:
        v = kwargs.get(k)
        if v is None:
            v = self._default(k)
        elif k in self._STEP_ATTR_TYPES:
            attr_type = self._STEP_ATTR_TYPES[k]

            if attr_type is callable:
                if not callable(v):
                    raise TypeError('%s is not callable: %r' % (k, v))
            elif not isinstance(v, attr_type):
                raise TypeError('%s is not an instance of %r: %r' % (
                    k, self._STEP_ATTR_TYPES[k], v))

        setattr(self, k, v)

def __repr__(self):
    kwargs = dict(
        (k, getattr(self, k))
        for k in self._STEP_ATTR_TYPES if hasattr(self, k))

    return '%s(%s)' % (
        self.__class__.__name__, ', '.join(
            '%s=%s' % (k, v)
            for k, v in sorted(kwargs.items())
            if v != self._default(k)))

def _default(self, k):
    if k in self._STEP_ATTR_DEFAULTS:
        return self._STEP_ATTR_DEFAULTS[k]()
    else:
        return None

def _pickle_safe(func):
    """Call no-args function *func*, returning *None* and ensuring
    that any exception raised is pickleable."""
    try:
        func()  # always return None
    except _TaskFailedException:
        raise  # we know these are pickleable
    except Exception as ex:
        raise Exception(repr(ex))  # we know this is pickleable

def _to_num_bytes(java_mem_str):
    if isinstance(java_mem_str, string_types):
        for i, magnitude in enumerate(('k', 'm', 'g', 't'), start=1):
            if java_mem_str.lower().endswith(magnitude):
                return int(java_mem_str[:-1]) * 1024 ** i

    return int(java_mem_str)

def __getattr__(self, name):
    """The glue that makes functions retriable, and returns other
    attributes from the wrapped object as-is."""
    x = getattr(self.__wrapped, name)

    if name in self.__unwrap_methods:
        return partial(x.__func__, self)
    elif hasattr(x, '__call__'):
        return self.__wrap_method_with_call_and_maybe_retry(x)
    else:
        return x

def __wrap_method_with_call_and_maybe_retry(self, f):
    """Wrap method f in a retry loop."""

    def call_and_maybe_retry(*args, **kwargs):
        backoff = self.__backoff
        tries = 0

        while not self.__max_tries or tries < self.__max_tries:
            try:
                return f(*args, **kwargs)
            except Exception as ex:
                if (self.__retry_if(ex) and
                    (tries < self.__max_tries - 1 or
                     not self.__max_tries)):
                    log.info('Got retriable error: %r' % ex)
                    log.info('Backing off for %.1f seconds' % backoff)
                    time.sleep(backoff)
                    tries += 1
                    backoff *= self.__multiplier
                    backoff = min(backoff, self.__max_backoff)
                else:
                    raise

    # pretend to be the original function
    call_and_maybe_retry.__doc__ = f.__doc__

    if hasattr(f, '__name__'):
        call_and_maybe_retry.__name__ = f.__name__

    return call_and_maybe_retry

def call_and_maybe_retry(*args, **kwargs):
    backoff = self.__backoff
    tries = 0

    while not self.__max_tries or tries < self.__max_tries:
        try:
            return f(*args, **kwargs)
        except Exception as ex:
            if (self.__retry_if(ex) and
                (tries < self.__max_tries - 1 or
                 not self.__max_tries)):
                log.info('Got retriable error: %r' % ex)
                log.info('Backing off for %.1f seconds' % backoff)
                time.sleep(backoff)
                tries += 1
                backoff *= self.__multiplier
                backoff = min(backoff, self.__max_backoff)
            else:
                raise

def _instance_profile(self):
    try:
        return (self._opts['iam_instance_profile'] or
                get_or_create_mrjob_instance_profile(
                    self.make_iam_client()))
    except botocore.exceptions.ClientError as ex:
        if _client_error_status(ex) != 403:
            raise
        log.warning(
            "Can't access IAM API, trying default instance profile: %s" %
            _FALLBACK_INSTANCE_PROFILE)
        return _FALLBACK_INSTANCE_PROFILE

def _service_role(self):
    try:
        return (self._opts['iam_service_role'] or
                get_or_create_mrjob_service_role(self.make_iam_client()))
    except botocore.exceptions.ClientError as ex:
        if _client_error_status(ex) != 403:
            raise
        log.warning(
            "Can't access IAM API, trying default service role: %s" %
            _FALLBACK_SERVICE_ROLE)
        return _FALLBACK_SERVICE_ROLE

def _check_name(self, name):
    if name is None:
        return

    if not isinstance(name, string_types):
        raise TypeError('name must be a string or None: %r' % (name,))

    if '/' in name:
        raise ValueError('names may not contain slashes: %r' % (name,))

def _check_type(self, type):
    if type not in self._SUPPORTED_TYPES:
        raise ValueError('bad path type %r, must be one of: %s' % (
            type, ', '.join(sorted(self._SUPPORTED_TYPES))))

def paths(self, type=None):
    """Get a set of all paths tracked by this WorkingDirManager."""
    paths = set()

    for path_type, path in self._typed_path_to_auto_name:
        if type is None or path_type == type:
            paths.add(path)

    for path_type, path in self._name_to_typed_path.values():
        if type is None or path_type == type:
            paths.add(path)

    return paths

def _interpolate_spark_script_path(self, path):
    if path in self._working_dir_mgr.paths():
        return self._dest_in_wd_mirror(
            path, self._working_dir_mgr.name('file', path)) or path
    else:
        return self._upload_mgr.uri(path)

def _check_and_fix_s3_dir(self, s3_uri):
    """Helper for __init__"""
    if not is_s3_uri(s3_uri):
        raise ValueError('Invalid S3 URI: %r' % s3_uri)
    if not s3_uri.endswith('/'):
        s3_uri = s3_uri + '/'

    return s3_uri

def _fix_opt(self, opt_key, opt_value, source):
    """Fix and check various EMR-specific options"""
    opt_value = super(EMRJobRunner, self)._fix_opt(
        opt_key, opt_value, source)

    # *_instance_bid_price
    if opt_key.endswith('_instance_bid_price'):
        if not opt_value:  # don't allow blank bid price
            return None

        try:
            if not float(opt_value):
                return None
        except ValueError:  # maybe EMR allows non-floats?
            pass

        return str(opt_value)  # should be str, not a number

    # additional_emr_info
    elif opt_key == 'additional_emr_info' and not isinstance(
            opt_value, string_types):
        return json.dumps(opt_value)

    # emr_configurations
    elif opt_key == 'emr_configurations':
        return [_fix_configuration_opt(c) for c in opt_value]

    # region
    elif opt_key == 'region':
        # don't allow blank region
        return opt_value or _DEFAULT_EMR_REGION

    # subnet should be None, a string, or a multi-item list
    elif opt_key == 'subnet':
        return _fix_subnet_opt(opt_value)

    else:
        return opt_value

def _fix_subnet_opt(subnet):
    """Return either None, a string, or a list with at least two items."""
    if subnet is None:
        return None

    if isinstance(subnet, string_types):
        return subnet

    subnet = list(subnet)
    if len(subnet) == 1:
        return subnet[0]
    else:
        return subnet

def _image_version_gte(self, version):
    """Check if the requested image version is greater than
    or equal to *version*. If the *release_label* opt is set,
    look at that instead.

    If you're checking the actual image version of a cluster, just
    use :py:func:`~mrjob.compat.version_gte` and
    :py:meth:`get_image_version`.
    """
    if self._opts['release_label']:
        return version_gte(
            self._opts['release_label'].lstrip('emr-'), version)
    else:
        return version_gte(self._opts['image_version'], version)

def make_s3_client(self, region_name=None):
    """Create a :py:mod:`boto3` S3 client,
    wrapped in a :py:class:`mrjob.retry.RetryWrapper`

    :param region: region to use to choose S3 endpoint.
    """
    # give a non-cryptic error message if boto3 isn't installed
    if boto3 is None:
        raise ImportError('You must install boto3 to connect to S3')

    kwargs = self._client_kwargs(region_name or self._s3_region)

    return _wrap_aws_client(boto3.client('s3', **kwargs))

def _client_kwargs(self, region_name):
    """Keyword args for creating resources or clients."""

    return dict(
        aws_access_key_id=self._aws_access_key_id,
        aws_secret_access_key=self._aws_secret_access_key,
        aws_session_token=self._aws_session_token,
        endpoint_url=self._s3_endpoint_url,
        region_name=(region_name or self._s3_region),
    )

def _s3_log_dir(self):
    """Get the URI of the log directory for this job's cluster."""
    if not self._s3_log_dir_uri:
        cluster = self._describe_cluster()
        log_uri = cluster.get('LogUri')
        if log_uri:
            self._s3_log_dir_uri = '%s%s/' % (
                log_uri.replace('s3n://', 's3://'), self._cluster_id)

    return self._s3_log_dir_uri

def _bash_is_bad(self):
    # hopefully, there will eventually be an image version
    # where this issue is fixed. See #1548
    return self._image_version_gte(_BAD_BASH_IMAGE_VERSION)

def _default_sh_bin(self):
    if self._bash_is_bad():
        return _BAD_BASH_SH_BIN
    else:
        return _GOOD_BASH_SH_BIN

def _sh_pre_commands(self):
    if self._bash_is_bad() and not self._opts['sh_bin']:
        return ['set -e']
    else:
        return []

def _cleanup_cloud_tmp(self):
    # delete all the files we created on S3
    if self._cloud_tmp_dir:
        try:
            log.info('Removing s3 temp directory %s...' %
                     self._cloud_tmp_dir)
            self.fs.rm(self._cloud_tmp_dir)
            self._cloud_tmp_dir = None
        except Exception as e:
            log.exception(e)

def _run(self):
    self._launch()
    self._finish_run()

def _finish_run(self):
    while True:
        try:
            self._wait_for_steps_to_complete()
            break
        except _PooledClusterSelfTerminatedException:
            self._relaunch()

def _check_output_not_exists(self):
    """Verify the output path does not already exist. This avoids
    provisioning a cluster only to have Hadoop refuse to launch.
    """
    try:
        if self.fs.exists(self._output_dir):
            raise IOError(
                'Output path %s already exists!' % (self._output_dir,))
    except botocore.exceptions.ClientError:
        pass

def _add_job_files_for_upload(self):
    """Add files needed for running the job (setup and input)
    to self._upload_mgr."""
    for path in self._py_files():
        self._upload_mgr.add(path)

    if self._opts['hadoop_streaming_jar']:
        self._upload_mgr.add(self._opts['hadoop_streaming_jar'])

    # upload JARs and (Python) scripts run by steps
    for step in self._get_steps():
        for key in 'jar', 'script':
            if step.get(key):
                self._upload_mgr.add(step[key])

def is_s3_uri(uri):
    """Return True if *uri* can be parsed into an S3 URI, False otherwise."""
    try:
        parse_s3_uri(uri)
        return True
    except ValueError:
        return False

def is_gcs_uri(uri):
    """Return True if *uri* can be parsed into an S3 URI, False otherwise.
    """
    try:
        parse_gcs_uri(uri)
        return True
    except ValueError:
        return False

def _libjar_paths(self):
    results = []

    # libjars should be in the working dir of the master node setup
    # script path, unless they refer to paths directly (file:///)
    for path in self._opts['libjars']:
        if path.startswith('file:///'):
            results.append(path[7:])  # keep leading slash
        else:
            results.append(posixpath.join(
                self._master_node_setup_working_dir(),
                self._master_node_setup_mgr.name('file', path)))

    return results

def _cp_to_local_cmd(self):
    """Command to copy files from the cloud to the local directory."""
    if self._opts['release_label']:
        # on the 4.x AMIs, hadoop isn't yet installed, so use AWS CLI
        return 'aws s3 cp'
    else:
        # on the 2.x and 3.x AMIs, use hadoop
        return 'hadoop fs -copyToLocal'

def _master_node_setup_working_dir(self):
    """Where to place files used by the master node setup script."""
    return '/home/hadoop/%s' % self._job_key

def _ssh_add_bin(self):
    # the args of the ssh-add binary
    return self._opts['ssh_add_bin'] or ['ssh-add']

def _ssh_launch(self, address, cmd_args):
    """Copy SSH keys if necessary, then launch the given command
    over SSH and return a Popen."""
    if '!' in address:
        self._ssh_add_key()

    args = self._ssh_cmd_args(address, cmd_args)

    log.debug('  > ' + cmd_line(args))
    try:
        return Popen(args, stdout=PIPE, stderr=PIPE)
    except OSError as ex:
        raise IOError(ex.strerror)

def _ssh_add_key(self):
    """Add ``self._ec2_key_pair_file`` to the ssh agent with ``ssh-add``.
    """
    args = self._ssh_add_bin + [
        '-t', '60', self._ec2_key_pair_file]

    log.debug('  > ' + cmd_line(args))

    try:
        p = Popen(args, stdout=PIPE, stderr=PIPE)
    except OSError as ex:
        raise IOError(ex.strerror)

    stdout, stderr = p.communicate()

    if p.returncode != 0:
        raise IOError(to_unicode(stderr))

def _ssh_bin(self):
    # the args of the ssh binary
    return self._opts['ssh_bin'] or ['ssh']

def _set_up_ssh_tunnel_and_hdfs(self):
    if hasattr(self.fs, 'hadoop'):
        self.fs.hadoop.set_hadoop_bin(self._ssh_hadoop_bin())
    self._set_up_ssh_tunnel()

def set_hadoop_bin(self, hadoop_bin):
    """Manually set the hadoop binary, as a list of args."""
    self._hadoop_bin = hadoop_bin

def _progress_html_from_tunnel(self):
    """Fetch progress by calling :py:func:`urlopen` on our ssh tunnel, or
    return ``None``."""
    if not self._ssh_tunnel_url:
        return None

    tunnel_config = self._ssh_tunnel_config()
    log.debug('  Fetching progress from %s at %s' % (
        tunnel_config['name'], self._ssh_tunnel_url))

    tunnel_handle = None
    try:
        tunnel_handle = urlopen(self._ssh_tunnel_url)
        return tunnel_handle.read()
    except Exception as e:
        log.debug('    failed: %s' % str(e))
        return None
    finally:
        if tunnel_handle:
            tunnel_handle.close()

def _parse_progress_from_job_tracker(html_bytes):
    """Pull (map_percent, reduce_percent) from running job from job tracker
    HTML as floats, or return (None, None).

    This assumes at most one running job (designed for EMR).
    """
    # snip out the Running Jobs section (ignore the header)
    start = html_bytes.rfind(b'Running Jobs')
    if start == -1:
        return None, None
    end = html_bytes.find(b'Jobs', start + len(b'Running Jobs'))
    if end == -1:
        end = None

    html_bytes = html_bytes[start:end]

    # search it for percents
    matches = _JOB_TRACKER_HTML_RE.findall(html_bytes)
    if len(matches) >= 2:
        return float(matches[0]), float(matches[1])
    else:
        return None, None

def _parse_progress_from_resource_manager(html_bytes):
    """Pull progress_precent for running job from job tracker HTML, as a
    float, or return None.

    This assumes at most one running job (designed for EMR).
    """
    # this is for EMR and assumes only one running job
    for line in html_bytes.splitlines():
        m = _RESOURCE_MANAGER_JS_RE.match(line)
        if m:
            return float(m.group('percent'))

    return None

def _describe_cluster(self):
    emr_client = self.make_emr_client()
    return emr_client.describe_cluster(
        ClusterId=self._cluster_id)['Cluster']

def _instance_type(self, role):
    """What instance type should we use for the given role?
    (one of 'MASTER', 'CORE', 'TASK')"""
    if role not in _INSTANCE_ROLES:
        raise ValueError

    # explicitly set
    if self._opts[role.lower() + '_instance_type']:
        return self._opts[role.lower() + '_instance_type']

    elif self._instance_is_worker(role):
        # using *instance_type* here is defensive programming;
        # if set, it should have already been popped into the worker
        # instance type option(s) by _fix_instance_opts() above
        return self._opts['instance_type'] or self._default_instance_type()
    else:
        return self._default_instance_type()

def _instance_is_worker(self, role):
    """Do instances of the given role run tasks? True for non-master
    instances and sole master instance."""
    if role not in _INSTANCE_ROLES:
        raise ValueError

    return (role != 'MASTER' or
            sum(self._num_instances(role)
                for role in _INSTANCE_ROLES) == 1)

def _num_instances(self, role):
    """How many of the given instance type do we want?"""
    if role not in _INSTANCE_ROLES:
        raise ValueError

    if role == 'MASTER':
        return 1  # there can be only one
    else:
        return self._opts['num_' + role.lower() + '_instances']

def _instance_bid_price(self, role):
    """What's the bid price for the given role (if any)?"""
    if role not in _INSTANCE_ROLES:
        raise ValueError

    return self._opts[role.lower() + '_instance_bid_price']

def _should_bootstrap_spark(self):
    """Return *bootstrap_spark* option if set; otherwise return
    true if our job has Spark steps."""
    if self._opts['bootstrap_spark'] is None:
        return self._has_spark_steps()
    else:
        return bool(self._opts['bootstrap_spark'])

def _emr_configurations(self):
    # don't keep two configs with the same Classification (#2097)
    return _deduplicate_emr_configurations(
        self._docker_emr_configurations() +
        self._opts['emr_configurations']
    )

def _action_on_failure(self):
    # don't terminate other people's clusters
    if (self._opts['emr_action_on_failure']):
        return self._opts['emr_action_on_failure']
    elif not self._add_steps_in_batch():
        # concurrent clusters don't allow CANCEL_ON_WAIT
        return 'CONTINUE'
    elif (self._opts['cluster_id'] or
            self._opts['pool_clusters']):
        return 'CANCEL_AND_WAIT'
    else:
        return 'TERMINATE_CLUSTER'

def _add_steps_in_batch(self):
    if self._opts['add_steps_in_batch'] is None:
        # by default, add steps in batch only when concurrent steps
        # are not possible
        return not self._image_version_gte('5.28.0')
    else:
        return self._opts['add_steps_in_batch']

def _build_master_node_setup_step(self):
    name = '%s: Master node setup' % self._job_key
    jar = self._script_runner_jar_uri()
    step_args = [self._upload_mgr.uri(self._master_node_setup_script_path)]

    return dict(
        Name=name,
        ActionOnFailure=self._action_on_failure(),
        HadoopJarStep=dict(
            Jar=jar,
            Args=step_args,
        )
    )

def _build_step(self, step_num):
    step = self._get_step(step_num)

    if step['type'] == 'streaming':
        method = self._streaming_step_hadoop_jar_step
    elif step['type'] == 'jar':
        method = self._jar_step_hadoop_jar_step
    elif _is_spark_step_type(step['type']):
        method = self._spark_step_hadoop_jar_step
    else:
        raise ValueError('Bad step type: %r' % (step['type'],))

    hadoop_jar_step = method(step_num)

    return dict(
        ActionOnFailure=self._action_on_failure(),
        HadoopJarStep=hadoop_jar_step,
        Name=self._step_name(step_num),
    )

def _streaming_step_hadoop_jar_step(self, step_num):
    jar, step_arg_prefix = self._get_streaming_jar_and_step_arg_prefix()

    args = (step_arg_prefix +
            self._hadoop_streaming_jar_args(step_num))

    return dict(Jar=jar, Args=args)

def _spark_step_hadoop_jar_step(self, step_num):
