def _get_cluster_info(self, key):
    if not self._cluster_id:
        return None

    cache = self._cluster_to_cache[self._cluster_id]

    if not cache.get(key):
        if key == 'master_private_ip':
            self._store_master_instance_info()
        else:
            self._store_cluster_info()

    return cache.get(key)

def _cat_log_lines(fs, path):
    """Yield lines from the given log.

    Log errors rather than raising them.
    """
    try:
        if not fs.exists(path):
            return
        for line in to_lines(fs.cat(path)):
            yield to_unicode(line)
    except (IOError, OSError) as e:
        log.warning("couldn't cat() %s: %r" % (path, e))

def _interpret_task_logs(
        self, log_interpretation, step_type, error_attempt_ids=(),
        partial=True):
    """Fetch task syslogs and stderr, and add 'task' to interpretation."""
    if 'task' in log_interpretation and (
            partial or not log_interpretation['task'].get('partial')):
        return   # already interpreted

    if not self._read_logs():
        return

    step_interpretation = log_interpretation.get('step') or {}

    application_id = step_interpretation.get('application_id')
    job_id = step_interpretation.get('job_id')
    output_dir = step_interpretation.get('output_dir')

    yarn = uses_yarn(self.get_hadoop_version())

    attempt_to_container_id = log_interpretation.get('history', {}).get(
        'attempt_to_container_id', {})

    if yarn:
        if not application_id:
            if not log_interpretation.get('no_job'):
                log.warning(
                    "Can't fetch task logs; missing application ID")
            return
    else:
        if not job_id:
            if not log_interpretation.get('no_job'):
                log.warning("Can't fetch task logs; missing job ID")
            return

    if self._step_type_uses_spark(step_type):
        interpret_func = _interpret_spark_logs
    else:
        interpret_func = _interpret_task_logs

    log_interpretation['task'] = interpret_func(
        self.fs,
        self._ls_task_logs(
            step_type,
            application_id=application_id,
            job_id=job_id,
            output_dir=output_dir,
            error_attempt_ids=error_attempt_ids,
            attempt_to_container_id=attempt_to_container_id,
        ),
        partial=partial,
        log_callback=_log_parsing_task_log)

def _interpret_spark_logs(fs, matches, partial=True, log_callback=None):
    result = {}
    errors = []

    for match in matches:
        stop_if_partial = False

        path = match['path']
        if log_callback:
            log_callback(path)

        interpretation = _parse_spark_log(_cat_log_lines(fs, path))

        result.update(interpretation)
        # don't _add_implied_job_id() because it doesn't work that way on Spark

        for error in interpretation.get('errors') or ():
            if 'spark_error' in error:
                error['spark_error']['path'] = path
                if error['spark_error']['num_lines'] > 1:
                    stop_if_partial = True
                    # still worth parsing all the errors in this log

            for id_key in 'attempt_id', 'container_id':
                if id_key in match:
                    error[id_key] = match[id_key]
            _add_implied_task_id(error)

            errors.append(error)

        if partial and stop_if_partial:
            result['partial'] = True
            break

    if errors:
        result['errors'] = errors

    return result

def _interpret_emr_step_syslog(fs, matches):
    """Extract information from step syslog (see :py:func:`_parse_step_log()`),
    which may be split into several chunks by timestamp"""
    # going to merge results for each log into final result
    errors = []
    result = {}

    for match in matches:
        path = match['path']

        interpretation = _parse_step_syslog(_cat_log_lines(fs, path))

        result.update(interpretation)
        for error in result.get('errors') or ():
            if 'hadoop_error' in error:
                error['hadoop_error']['path'] = path
            _add_implied_task_id(error)
            errors.append(error)

    _add_implied_job_id(result)
    if errors:
        result['errors'] = errors

    return result

def _interpret_emr_step_stderr(fs, matches):
    """Extract information from step stderr (see
    :py:func:`~mrjob.logs.task._parse_task_stderr()`),
    which may be split into several chunks by timestamp"""
    for match in matches:
        path = match['path']

        error = _parse_task_stderr(_cat_log_lines(fs, path))

        if error:
            error['path'] = path
            # We're essentially just tailing the stderr log, so stop when we
            # find an error.
            return dict(errors=[dict(task_error=error)])

    return {}

def _attempt_id_to_task_id(attempt_id):
    """Convert e.g. ``'attempt_201601081945_0005_m_000005_0'``
    to ``'task_201601081945_0005_m_000005'``"""
