def _cmdenv(self):
    env = super(EMRJobRunner, self)._cmdenv()

    return combine_dicts(self._docker_cmdenv(), env)

def _docker_image(self):
    """Special-case the "library" registry which is implied on Docker Hub
    but needs to be specified explicitly on EMR."""
    image = self._opts['docker_image']

    if not image:
        return None
    elif '/' in image:
        return image
    else:
        return 'library/' + image

def _docker_registry(self):
    """Infer the trusted docker registry from the docker image."""
    image = self._docker_image()

    if not image:
        return None
    else:
        return image.split('/')[0]

def _docker_cmdenv(self):
    image = self._docker_image()

    if not image:
        return {}

    env = dict(
        YARN_CONTAINER_RUNTIME_TYPE='docker',
        YARN_CONTAINER_RUNTIME_DOCKER_IMAGE=image,
    )

    if self._opts['docker_client_config']:
        env['YARN_CONTAINER_RUNTIME_DOCKER_CLIENT_CONFIG'] = (
            self._opts['docker_client_config'])

    if self._opts['docker_mounts']:
        env['YARN_CONTAINER_RUNTIME_DOCKER_MOUNTS'] = ','.join(
            self._opts['docker_mounts'])

    return env

def _docker_emr_configurations(self):
    registry = self._docker_registry()

    if not registry:
        return []

    registries = ','.join(['local', registry])

    return [
        dict(
            Classification='container-executor',
            Configurations=[
                dict(
                    Classification='docker',
                    Properties={
                        'docker.trusted.registries': registries,
                        'docker.privileged-containers.registries': (
                            registries),
                    },
                ),
            ],
            Properties={},
        ),
    ]

def md5sum(self, path):
    k = self._get_s3_key(path)
    if not k:
        raise IOError('Key %r does not exist' % (path,))
    return k.e_tag.strip('"')

def _cat_file(self, path):
    # stream lines from the s3 key
    s3_key = self._get_s3_key(path)
    body = s3_key.get()['Body']

    return decompress(body, path)

def strip_microseconds(delta):
    """Return the given :py:class:`datetime.timedelta`, without microseconds.

    Useful for printing :py:class:`datetime.timedelta` objects.
    """
    return timedelta(delta.days, delta.seconds)

def _round_up_to_next_second(td):
    """Round up to the next second because that's how EMR bills."""
    if td.microseconds:
        return strip_microseconds(td) + timedelta(seconds=1)
    else:
        return td

def _format_timedelta(time):
    """Format a timedelta for use in a columnar format. This just
    tweaks stuff like ``'3 days, 9:00:00'`` to line up with
    ``'3 days, 10:00:00'``
    """
    result = str(strip_microseconds(time))

    parts = result.split()
    if len(parts) == 3 and len(parts[-1]) == 7:
        return '%s %s  %s' % tuple(parts)
    else:
        return result

def _create_zip_file(path):
    try:
        return ZipFile(path, mode='w', compression=ZIP_DEFLATED)
    except RuntimeError:  # zlib not available
        return ZipFile(path, mode='w', compression=ZIP_STORED)

def _job_script_module_name(self):
