def _make_cluster_lock(job_key, expiry):
    """Return the contents of a tag used to lock a cluster.

    *expiry* is the unix timestamp for when the lock is no longer valid"""
    return '%s %.6f' % (job_key, expiry)

def _parse_cluster_lock(lock):
    """Return (job_key, expiry) or raise ValueError

    Raises TypeError if *lock* is not a string.
    """
    if not isinstance(lock, (string_types)):
        raise TypeError

    job_key, expiry_str = lock.split(' ')

    try:
        expiry = float(expiry_str)
    except TypeError:
        raise ValueError

    return job_key, expiry

def _igs_for_same_role_satisfy(actual_igs, requested_ig):
    """Does the *actual* list of instance groups satisfy the *requested*
    one?
    """
    # bid price/on-demand
    if not all(_ig_satisfies_bid_price(ig, requested_ig) for ig in actual_igs):
        return False

    # memory
    if not all(_ig_satisfies_mem(ig, requested_ig) for ig in actual_igs):
        return False

    # EBS volumes
    if not all(_ebs_satisfies(ig, requested_ig) for ig in actual_igs):
        return False

    # CPU (this returns # of compute units or None)
    return _igs_satisfy_cpu(actual_igs, requested_ig)

def _ig_satisfies_bid_price(actual_ig, requested_ig):
    """Does the actual instance group definition satisfy the bid price
    (or lack thereof) of the requested instance group?
    """
    # _instance_groups_satisfy() already verified *requested_ig* is a dict

    # on-demand instances satisfy every bid price
    if actual_ig['Market'] == 'ON_DEMAND':
        return True

    if requested_ig.get('Market', 'ON_DEMAND') == 'ON_DEMAND':
        log.debug('    spot instance, requested on-demand')
        return False

    if actual_ig['BidPrice'] == requested_ig.get('BidPrice'):
        return True

    try:
        if float(actual_ig['BidPrice']) >= float(requested_ig.get('BidPrice')):
            return True
        else:
            # low bid prices mean cluster is more likely to be
            # yanked away
            log.debug('    bid price too low')
            return False
    except ValueError:
        log.debug('    non-float bid price')
        return False

def _ig_satisfies_mem(actual_ig, requested_ig):
    """Does the actual instance group satisfy the memory requirements of
    the requested instance group?"""
    actual_type = actual_ig['InstanceType']
    requested_type = requested_ig.get('InstanceType')

    # this works even for unknown instance types
    if actual_type == requested_type:
        return True

    try:
        if (EC2_INSTANCE_TYPE_TO_MEMORY[actual_type] >=
                EC2_INSTANCE_TYPE_TO_MEMORY[requested_type]):
            return True
        else:
            log.debug('    too little memory')
            return False
    except KeyError:
        log.debug('    unknown instance type')
        return False

def _ebs_volumes_satisfy(actual_volumes, req_volumes):
    """Does the given list of actual EBS volumes satisfy the given request?

    Just compare them one by one (we want each actual device to be
    bigger/faster; just having the same amount of capacity or iops
    isn't enough).
    """
    if not isinstance(req_volumes, (list, tuple)):
        return False

    if len(req_volumes) > len(actual_volumes):
        log.debug('    more EBS volumes requested than available')
        return False

    return all(_ebs_volume_satisfies(a, r)
               for a, r in zip(actual_volumes, req_volumes))

def _ebs_volume_satisfies(actual_volume, req_volume):
    """Does the given actual EBS volume satisfy the given request?"""
    if not isinstance(req_volume, dict):
        return False

    if req_volume.get('VolumeType') != actual_volume.get('VolumeType'):
        log.debug('    wrong EBS volume type')
        return False

    if not req_volume.get('SizeInGB', 0) <= actual_volume.get('SizeInGB', 0):
        log.debug('    EBS volume too small')
        return False

    # Iops isn't really "optional"; it has to be set if volume type is
    # io1 and not set otherwise
    if not (req_volume.get('Iops', 0) <= actual_volume.get('Iops', 0)):
        log.debug('    EBS volume too slow')
        return False

    return True

def _fleet_for_same_role_satisfies(actual_fleet, req_fleet):
    # match up instance types
    actual_specs = {spec['InstanceType']: spec
                    for spec in actual_fleet['InstanceTypeSpecifications']}
    try:
        req_specs = {spec['InstanceType']: spec
                     for spec in req_fleet['InstanceTypeConfigs']}
    except (TypeError, KeyError):
        return False

    if set(actual_specs) - set(req_specs):
        log.debug('    fleet may include wrong instance types')
        return False

    if not all(_fleet_spec_satsifies(actual_specs[t], req_specs[t])
               for t in actual_specs):
        return False

    # capacity
    actual_on_demand = actual_fleet.get('ProvisionedOnDemandCapacity', 0)
    req_on_demand = req_fleet.get('TargetOnDemandCapacity', 0)

    if not isinstance(req_on_demand, integer_types):
        return False

    if req_on_demand > actual_on_demand:
        log.debug('    not enough on-demand capacity')
        return False

    actual_spot = actual_fleet.get('ProvisionedSpotCapacity', 0)
    req_spot = req_fleet.get('TargetSpotCapacity', 0)

    if not isinstance(req_spot, integer_types):
        return False

    # allow extra on-demand instances to serve as spot instances
    if req_spot > actual_spot + (actual_on_demand - req_on_demand):
        log.debug('    not enough spot capacity')

    # handle TERMINATE_CLUSTER timeout action. This really doesn't play
    # well with pooling anyhow
    if _get_timeout_action(actual_fleet) == 'TERMINATE_CLUSTER':
        if _get_timeout_action(req_fleet) != 'TERMINATE_CLUSTER':
            log.debug('    self-terminating fleet not requested')
            return False

        if (_get_timeout_duration(actual_fleet) <
                _get_timeout_duration(req_fleet)):
            log.debug('    fleet may self-terminate prematurely')
            return False

    return True

def _get_timeout_action(fleet):
    return fleet.get(
        'LaunchSpecifications', {}).get(
        'SpotSpecification', {}).get(
        'TimeoutAction')

def _get_timeout_duration(fleet):
    return fleet.get(
        'LaunchSpecifications', {}).get(
        'SpotSpecification', {}).get(
        'TimeoutDurationMinutes', 0.0)

def _pick_spark_tmp_dir(self):
    if self._opts['spark_tmp_dir']:
        return self.fs.join(self._opts['spark_tmp_dir'], self._job_key)
    else:
        master = self._spark_master() or 'local'
        if master.startswith('local'):  # including local-cluster
            # need a local temp dir
            # add "-spark" so we don't collide with default local temp dir
            return os.path.join(
                gettempdir(), self._job_key + '-spark')
        else:
            # use HDFS (same default as HadoopJobRunner)
            return posixpath.join(
                fully_qualify_hdfs_path('tmp/mrjob'), self._job_key)

def _run_steps_on_spark(self):
    steps = self._get_steps()

    for group in self._group_steps(steps):
        step_num = group['step_num']
        last_step_num = step_num + len(group['steps']) - 1

        # the Spark harness can run several streaming steps in one job
        if step_num == last_step_num:
            step_desc = 'step %d' % (step_num + 1)
        else:
            step_desc = 'steps %d-%d' % (step_num + 1, last_step_num + 1)

        log.info('Running %s of %d' % (step_desc, len(steps)))

        self._run_step_on_spark(group['steps'][0], step_num, last_step_num)

def _is_permanent_boto3_error(ex):
    """Used to disable S3Filesystem when boto3 is installed but
    credentials aren't set up."""
    return isinstance(ex, botocore.exceptions.NoCredentialsError)

def _has_streaming_steps(self):
    """Are any of our steps "streaming" steps that would normally run
    on Hadoop Streaming?"""
    return any(step['type'] == 'streaming' for step in self._get_steps())

def _spark_script_path(self, step_num):
    """For streaming steps, return the path of the harness script
    (and handle other spark step types the usual way)."""
    step = self._get_step(step_num)

    if step['type'] == 'streaming':
        return self._spark_harness_path()
    else:
        return super(SparkMRJobRunner, self)._spark_script_path(step_num)

def _check_step(step, step_num):
    """Check that the given step description is for a MRStep
    with no input manifest"""
    if step.get('type') != 'streaming':
        raise ValueError(
            'step %d has unexpected type: %r' % (
                step_num, step.get('type')))

    if step.get('input_manifest'):
        raise NotImplementedError(
            'step %d uses an input manifest, which is unsupported')

    for mrc in ('mapper', 'reducer'):
        _check_substep(step, step_num, mrc)

def _discard_key_and_flatten_values(rdd, sort_values=False):
    """Helper function for :py:func:`_run_combiner` and
    :py:func:`_shuffle_and_sort`.

    Given an RDD containing (key, [line1, line2, ...]), discard *key*
    and return an RDD containing line1, line2, ...

    Guarantees that lines in the same list will end up in the same partition.

    If *sort_values* is true, sort each list of lines before flattening it.
    """
    if sort_values:
        def map_f(key_and_lines):
            return sorted(key_and_lines[1])
    else:
        def map_f(key_and_lines):
            return key_and_lines[1]

    return rdd.flatMap(map_f, preservesPartitioning=True)

def __getattr__(self, name):
    # don't confuse pickling (e.g. __getstate__())
    if name.startswith('__'):
        raise AttributeError(name)

    # go through non-disabled filesystems and pick the first
    # attribute with a matching name
    for fs_name in self._fs_names:
        if fs_name in self._disabled:
            continue

        fs = getattr(self, fs_name)
        if hasattr(fs, name):
            log.warning(
                'passing %s() through to the top-level filesystem is'
                ' deprecated and going away in v0.7.0. Try'
                ' fs.%s.%s(...) instead' % (name, fs_name, name))
            return getattr(fs, name)

    raise AttributeError(name)

def touchz(self, path):
    try:
        self.invoke_hadoop(['fs', '-touchz', path])
    except CalledProcessError:
        raise IOError("Could not touchz %s" % path)

def can_handle_path(self, path):
    """We can handle any path handled by any (non-disabled) filesystem."""
    for fs_name in self._fs_names:
        if fs_name in self._disabled:
            continue

        fs = getattr(self, fs_name)
        if fs.can_handle_path(path):
            return True

    return False

def _handle(self, name, path_to_handle, *args, **kwargs):
    """Call method named *name* on the first (non-disabled) filesystem
    that says it can handle every path in *paths_to_handle*. If it raises
    an exception, either disable the filesystem and continue, or
    re-raise the exception."""
    for fs_name in self._fs_names:
        if fs_name in self._disabled:
            continue

        fs = getattr(self, fs_name)
        if not fs.can_handle_path(path_to_handle):
            continue

        try:
            return getattr(fs, name)(*args, **kwargs)
        except Exception as ex:
            if (fs_name in self._disable_if and
                    self._disable_if[fs_name](ex)):
                log.debug('disabling %s fs: %r' % (fs_name, ex))

                self._disabled.add(fs_name)
            else:
                raise

    raise IOError("Can't handle path: %s" % path_to_handle)

def _do(self, name, path):
    """Handle the common case, where a method operates on a single path."""
    return self._handle(name, path, path)

def _cat_file(self, path):
    # mrjob/runner.py accesses this directly for efficiency
    return self._do('_cat_file', path)

def md5sum(self, path):
    blob = self._get_blob(path)
    if not blob:
        raise IOError('Object %r does not exist' % (path,))
    return binascii.hexlify(b64decode(blob.md5_hash)).decode('ascii')

def md5sum(self, path):
    """Generate the md5 sum of the file at *path*"""
    raise NotImplementedError

def _md5sum_file(self, fileobj, block_size=(512 ** 2)):  # 256K default
    md5 = hashlib.md5()
    while True:
        data = fileobj.read(block_size)
        if not data:
            break
        md5.update(data)
    return md5.hexdigest()

def md5sum(self, path):
    path = _from_file_uri(path)
    with open(path, 'rb') as f:
        return self._md5sum_file(f)

def get_hadoop_bin(self):
    """Return the hadoop binary, searching for it if need be."""
    if self._hadoop_bin is None:
        self._hadoop_bin = self._find_hadoop_bin()
    return self._hadoop_bin

def exists(self, path_glob):
    """Does the given path exist?

    If dest is a directory (ends with a "/"), we check if there are
    any files starting with that path.
    """
    try:
        return_code = self.invoke_hadoop(
            ['fs', '-ls', path_glob],
            ok_returncodes=[0, -1, 255],
            ok_stderr=[_HADOOP_LS_NO_SUCH_FILE])

        return (return_code == 0)
    except CalledProcessError:
        raise IOError("Could not check path %s" % path_glob)

def can_handle_path(self, path):
    """Can we handle this path at all?"""
    False

def client(self):
    return google.cloud.storage.client.Client(
        project=self._project_id, credentials=self._credentials)

def mkdir(self, path):
    """Does not actually create a directory on GCS (because GCS doesn't
    have directories), but creates the underlying bucket if it does not
    exist already.
    """
    bucket_name, base_name = parse_gcs_uri(path)

    try:
        self.get_bucket(bucket_name)
    except google.api_core.exceptions.NotFound:
        self.create_bucket(bucket_name)

def touchz(self, path):
    # check if already exists
    old_blob = self._get_blob(path)
    if old_blob:
        raise IOError('Non-empty file %r already exists!' % (path,))

    self._blob(path).upload_from_string(b'')

def get_bucket(self, bucket_name):
    """Return a :py:class:`google.cloud.storage.bucket.Bucket`
    Raises an exception if the bucket does not exist."""
    return self.client.get_bucket(bucket_name)

def create_bucket(self, name,
                  location=None, object_ttl_days=None):
    """Create a bucket on GCS, optionally setting location constraint.
    and time-to-live."""
    bucket = self.client.bucket(name)

    if location is None:
        location = self._location
    elif not location:
        location = None  # leave a way to use the API default

    bucket.create(location=location)

    if object_ttl_days is None:
        object_ttl_days = self._object_ttl_days

    if object_ttl_days:
        bucket.lifecycle_rules = [
            dict(
                action=dict(type='Delete'),
                condition=dict(age=object_ttl_days)
            )
        ]

def _get_blob(self, uri, chunk_size=None):
    # NOTE: chunk_size seems not to work well with downloading
    bucket_name, blob_name = parse_gcs_uri(uri)
    bucket = self.client.get_bucket(bucket_name)
    return bucket.get_blob(blob_name, chunk_size=chunk_size)

def _blob(self, uri, chunk_size=None):
    # NOTE: chunk_size seems not to work well with downloading
    bucket_name, blob_name = parse_gcs_uri(uri)
    bucket = self.client.get_bucket(bucket_name)
    return bucket.blob(blob_name, chunk_size=chunk_size)

def du(self, path_glob):
    """Get the size of all files matching path_glob."""
    return sum(blob.size for uri, blob in self._ls(path_glob))

def rm(self, path_glob):
    """Remove all files matching the given glob."""
    for uri, blob in self._ls(path_glob):
        blob.delete()

def ls(self, path_glob):
    for uri, blob in self._ls(path_glob):
        # don't return directory "blobs"
        if uri.endswith('/'):
            continue

        yield uri

def exists(self, path_glob):
    """Does the given path exist?

    If dest is a directory (ends with a "/"), we check if there are
    any files starting with that path.
    """
    try:
        paths = self.ls(path_glob)
    except:
        paths = []
    return any(paths)

def cat(self, path_glob):
    """cat all files matching **path_glob**, decompressing if necessary

    This yields bytes, which don't necessarily correspond to lines
    (see #1544). If multiple files are catted, yields ``b''`` between
    each file.
    """
    for i, filename in enumerate(self.ls(path_glob)):
        if i > 0:
            yield b''  # mark end of previous file

        for line in self._cat_file(filename):
            yield line

def du(self, path_glob):
    """Get the size of all files matching path_glob."""
    return sum(key.size for uri, key in self._ls(path_glob))

def rm(self, path_glob):
    """Remove all files matching the given glob."""
    for uri, key in self._ls(path_glob):
        log.debug('deleting ' + uri)
        key.delete()

def mkdir(self, path):
    """Make a directory. This doesn't actually create directories on S3
    (because there is no such thing), but it will create the corresponding
    bucket if it doesn't exist.
    """
    bucket_name, key_name = parse_s3_uri(path)

    client = self.make_s3_client()

    try:
        client.head_bucket(Bucket=bucket_name)
    except botocore.exceptions.ClientError as ex:
        if _client_error_status(ex) != 404:
            raise

        self.create_bucket(bucket_name)

def du(self, path_glob):
    path_glob = _from_file_uri(path_glob)
    return sum(os.path.getsize(path) for path in self.ls(path_glob))

def ls(self, path_glob):
    bare_path_glob = _from_file_uri(path_glob)
    uri_scheme = path_glob[0:-len(bare_path_glob)]  # 'file:///' or ''

    for path in glob.glob(bare_path_glob):
        if os.path.isdir(path):
            for dirname, _, filenames in os.walk(path, followlinks=True):
                for filename in filenames:
                    yield uri_scheme + os.path.join(dirname, filename)
        else:
            yield uri_scheme + path

def exists(self, path_glob):
    path_glob = _from_file_uri(path_glob)
    return bool(glob.glob(path_glob))

def rm(self, path_glob):
    path_glob = _from_file_uri(path_glob)
    for path in glob.glob(path_glob):
        if os.path.isdir(path):
            log.debug('Recursively deleting %s' % path)
            shutil.rmtree(path)
        else:
            log.debug('Deleting %s' % path)
            os.remove(path)

def _from_file_uri(path_or_uri):
    if is_uri(path_or_uri):
        if path_or_uri.startswith('file:///'):
            return path_or_uri[7:]  # keep last /
        else:
            raise ValueError('Not a file:/// URI')
    else:
        return path_or_uri

def _sum_counters(*counters_list):
    """Combine many maps from group to counter to amount."""
    result = {}

    for counters in counters_list:
        for group, counter_to_amount in counters.items():
            for counter, amount in counter_to_amount.items():
                result.setdefault(group, {})
                result[group].setdefault(counter, 0)
                result[group][counter] += amount

    return result

def _interpret_history_log(fs, matches):
    """Extract counters and errors from history log.

    Matches is a list of dicts with the keys *job_id* and *yarn*
    (see :py:func:`_ls_history_logs()`)

    We expect *matches* to contain at most one match; further matches
    will be ignored.

    Returns a dictionary with the keys *counters* and *errors*.
    """
    # we expect to go through this for loop 0 or 1 times
    for match in matches:
        path = match['path']

        if match['yarn']:
            # not yet implemented
            result = _parse_yarn_history_log(_cat_log_lines(fs, path))
        else:
            result = _parse_pre_yarn_history_log(_cat_log_lines(fs, path))

        # patch path, task_id, etc. into errors
        for error in result.get('errors') or ():
            if 'hadoop_error' in error:
                error['hadoop_error']['path'] = path
            _add_implied_task_id(error)

        return result

    return {}

def _extract_yarn_counters(counters_record):
    """Convert Avro-Json counter data structure to our
    group -> counter -> amount format.

    This deals gracefully with unexpected data structures.
    """
    if not isinstance(counters_record, dict):
        return {}

    group_records = counters_record.get('groups')
    if not isinstance(group_records, list):
        return {}

    counters = {}

    for group_record in group_records:
        if not isinstance(group_record, dict):
            continue

        group = group_record.get('displayName')
        if not isinstance(group, string_types):
            continue

        counter_records = group_record.get('counts')
        if not isinstance(counter_records, list):
            continue

        for counter_record in counter_records:
            counter = counter_record.get('displayName')
            if not isinstance(counter, string_types):
                continue

            # in YARN, counters can have an amount of 0. The Hadoop command
            # prints them out, so we'll parse them
            amount = counter_record.get('value')
            if not (isinstance(amount, integer_types)):
                continue

            counters.setdefault(group, {})
            counters[group].setdefault(counter, 0)
            counters[group][counter] += amount

    return counters

def _pre_yarn_history_unescape(s):
    """Un-escape string from a pre-YARN history file."""
    return _PRE_YARN_HISTORY_ESCAPE_RE.sub(r'\1', s)

def _check_for_nonzero_return_code(reason):
    """Given a reason for cluster termination, check if it's because
    a bootstrap action terminated with an error.

    If it is, return a dictionary with the keys action_num (0-indexed
    bootstrap action number) and node_id (a string). Otherwise return None.
    """
    m = _BOOTSTRAP_NONZERO_RETURN_CODE_RE.match(reason)

    if m:
        return _extract_action_num_and_node_id(m)
    else:
        return None

def _extract_action_num_and_node_id(m):
    """Helper method: Extract *action_num* and *node_id* from the given regex
    match. Convert *action_num* to a 0-indexed integer."""
    return dict(
        action_num=(int(m.group('action_num')) - 1),
        node_id=m.group('node_id'),
    )

def _ls_logs(fs, log_dir_stream, matcher, is_spark=False, **kwargs):
    """Return a list matches against log files. Used to implement
    ``_ls_*_logs()`` functions.

    This yields dictionaries with ``path`` set to matching log path, and
    other information (e.g. corresponding job_id) returned by *matcher*

    *fs* is a :py:class:`mrjob.fs.Filesystem`

    *log_dir_stream* is a sequence of lists of log dirs. The idea is that
    there may be copies of the same logs in multiple places (e.g.
    on S3 and by SSHing into nodes) and we want to list them all without
    finding duplicate copies. This function will go through the lists of
    log dirs in turn, stopping if it finds any matches from a list.

    *matcher* is a function that takes (log_path, **kwargs)
    and returns either None (no match) or a dictionary with information
    about the path (e.g. the corresponding job_id). It's okay to return
    an empty dict.
    """
    # wrapper for fs.ls() that turns IOErrors into warnings
    def _fs_ls(path):
        try:
            log.debug('    listing logs in %s' % log_dir)
            if fs.exists(log_dir):
                for path in fs.ls(log_dir):
                    yield path
        except (IOError, OSError) as e:
            log.warning("couldn't ls() %s: %r" % (log_dir, e))

    for log_dirs in log_dir_stream:
        if isinstance(log_dirs, str):
            raise TypeError

        matched = False

        for log_dir in log_dirs:
            matches = []

            for path in _fs_ls(log_dir):
                match = matcher(path, **kwargs)
                if match is not None:
                    match['path'] = path
                    matches.append(match)

            if matches:
                matched = True

                if is_spark:
                    matches = _sort_for_spark(matches)
                else:
                    matches = _sort_by_recency(matches)

                for match in matches:
                    yield match

        if matched:
            return  # e.g. don't check S3 if we can get logs via SSH

def _fs_ls(path):
    try:
        log.debug('    listing logs in %s' % log_dir)
        if fs.exists(log_dir):
            for path in fs.ls(log_dir):
                yield path
    except (IOError, OSError) as e:
        log.warning("couldn't ls() %s: %r" % (log_dir, e))

def _sort_by_recency(ds):
    """Sort the given list/sequence of dicts containing IDs so that the
    most recent ones come first (e.g. to find the best error, or the best
    log file to look for an error in).
    """
    return sorted(ds, key=_time_sort_key, reverse=True)

def _match_history_log_path(path, job_id=None):
    """Yield paths/uris of all job history files in the given directories,
    optionally filtering by *job_id*.
    """
    m = _HISTORY_LOG_PATH_RE.match(path)
    if not m:
        return None

    if not (job_id is None or m.group('job_id') == job_id):
        return None

    # TODO: couldn't manage to include .jhist in regex; an optional
    # group has less priority than a non-greedy match, apparently
    return dict(job_id=m.group('job_id'), yarn='.jhist' in m.group('suffix'))

def _log_key(match):
    """Helper method for _ls_task_logs() and _ls_spark_task_logs()."""
    return tuple((k, v) for k, v in sorted(match.items())
                 if k not in ('log_type', 'path'))

def _pick_error(self, log_interpretation, step_type):
    """Pick probable cause of failure (only call this if job fails)."""
    from mrjob.logs.errors import _pick_error_attempt_ids
    from mrjob.logs.errors import _pick_error
    logs_needed = self._logs_needed_to_pick_error(step_type)

    if self._read_logs() and not all(
            log_type in log_interpretation for log_type in logs_needed):
        log.info('Scanning logs for probable cause of failure...')

        if 'step' in logs_needed:
            self._interpret_step_logs(log_interpretation, step_type)

        if 'history' in logs_needed:
            self._interpret_history_log(log_interpretation)

        if 'task' in logs_needed:
            error_attempt_ids = _pick_error_attempt_ids(log_interpretation)

            self._interpret_task_logs(
                log_interpretation, step_type, error_attempt_ids)

    return _pick_error(log_interpretation)

def _logs_needed_to_pick_error(self, step_type):
    """We don't need all the logs when interpreting Spark steps"""
    if self._step_type_uses_spark(step_type):
        if self._spark_deploy_mode() == 'cluster':
            return ('step', 'task')
        else:
            return ('step',)
    else:
        return ('step', 'history', 'task')

def yield_record_strings(lines):
    record_lines = []
    start_line = 0

    for line_num, line in enumerate(lines):
        record_lines.append(line)
        if line.endswith(' .\n'):
            yield start_line, len(record_lines), ''.join(record_lines)
            record_lines = []
            start_line = line_num + 1

def yield_records():
    for record in _parse_hadoop_log4j_records(lines):
        if record_callback:
            record_callback(record)
        yield record

def _interpret_new_dataproc_step_stderr(step_interpretation, new_lines):
    """Incrementally update *step_interpretation* (a dict) with information
    from new lines read from Hadoop job driver output on Dataproc."""
    return _parse_step_syslog_from_log4j_records(
        _parse_hadoop_log4j_records(new_lines),
        step_interpretation)

def _interpret_hadoop_jar_command_stderr(lines, record_callback=None):
    """Parse *lines* from the ``hadoop jar`` command's stderr (lines can be
    either bytes or unicode). Works like :py:func:`_parse_step_syslog` (same
    return format) with a few extra features to handle the output of the
    ``hadoop jar`` command on the fly:

    - Pre-filters non-log4j stuff from Hadoop Streaming so it doesn't
      get treated as part of a multi-line message
    - Optionally calls *record_callback* for each log4j record (see
      :py:func:`~mrjob.logs.log4j._parse_hadoop_log4j_records`).
    """
    def pre_filter(line):
        return bool(_HADOOP_STREAMING_NON_LOG4J_LINE_RE.match(line))

    def yield_records():
        for record in _parse_hadoop_log4j_records(
                lines, pre_filter=pre_filter):
            if record_callback:
                record_callback(record)
            yield record

    result = _parse_step_syslog_from_log4j_records(yield_records())

    _add_implied_job_id(result)
    for error in result.get('errors') or ():
        _add_implied_task_id(error)

    return result

def yield_records():
    for record in _parse_hadoop_log4j_records(
            lines, pre_filter=pre_filter):
        if record_callback:
            record_callback(record)
        yield record

def sort_key(key_and_error):
    key, error = key_and_error

    # key[0] is 'container_id' or 'time_key'
    return (bool(error.get('task_error')),
            key[0] == 'container_id',
            key[1:])

def _pick_spark_errors(errors):
    """Pick the shortest Spark error with a traceback."""
    def sort_key(error):
        spark_error = error['spark_error']
        msg = spark_error.get('message') or ''
        num_lines = spark_error.get('num_lines') or 1

        return (
            _PYTHON_TRACEBACK_HEADER in msg,
            num_lines > 1,
            -num_lines,
        )

    return sorted(
        (e for e in errors if e.get('spark_error')),
        key=sort_key, reverse=True)

def sort_key(error):
    spark_error = error['spark_error']
    msg = spark_error.get('message') or ''
    num_lines = spark_error.get('num_lines') or 1

    return (
        _PYTHON_TRACEBACK_HEADER in msg,
        num_lines > 1,
        -num_lines,
    )

def _format_error(error):
    """Return string to log/print explaining the given error."""
    # it's just sad if we error while trying to explain an error
    try:
        return _format_error_helper(error)
    except:
        return json.dumps(error, indent=2, sort_keys=True)

def _format_error_helper(error):
    """Return string to log/print explaining the given error."""
    result = ''

    spark_error = error.get('spark_error')
    if spark_error:
        spark_error = _trim_spark_error(spark_error)

        result += spark_error.get('message', '')

        if spark_error.get('path'):
            result += '\n\n(from %s)' % _describe_source(spark_error)

        # spark errors typically include both java and Python stacktraces,
        # so it's not helpful to print hadoop/task errors (and there probably
        # wouldn't be any)
    else:
        hadoop_error = error.get('hadoop_error')
        if hadoop_error:
            result += hadoop_error.get('message', '')

            if hadoop_error.get('path'):
                result += '\n\n(from %s)' % _describe_source(hadoop_error)

        # for practical purposes, there's always a Java error with a message,
        # so don't worry too much about spacing.

        task_error = error.get('task_error')
        if task_error:
            if hadoop_error:
                result += '\n\ncaused by:\n\n%s' % (
                    task_error.get('message', ''))
            else:
                result += task_error.get('message', '')

            if task_error.get('path'):
                result += '\n\n(from %s)' % _describe_source(task_error)

    split = error.get('split')
    if split and split.get('path'):
        result += '\n\nwhile reading input from %s' % _describe_source(split)

    return result

def _describe_source(d):
    """return either '<path>' or 'line N of <path>' or 'lines M-N of <path>'.
    """
    path = d.get('path') or ''

    if 'num_lines' in d and 'start_line' in d:
        if d['num_lines'] == 1:
            return 'line %d of %s' % (d['start_line'] + 1, path)
        else:
            return 'lines %d-%d of %s' % (
                d['start_line'] + 1, d['start_line'] + d['num_lines'], path)
    else:
        return path

def _step_sort_key(d):
    """Sort by timestamp and step"""
    return (
        _timestamp(d),
        _step_num(d),
    )

def _id_part(id, i):
    """Get the ith part of some container ID, e.g.
    container_1567013493699_0003_01_000002. If *id* is None
    or too short, return ''"""
    parts = (id or '').split('_')

    if i >= len(parts):
        return ''
    else:
        return parts[i]

def _timestamp(d):
    """cluster timestamp. the first number in any ID.

    For example, in container_1567013493699_0003_01_000002, it's
    1567013493699."""
    return _id_part(_any_id(d), 1)

def _step_num(d):
    """Number that indicates this is the nth task to be launched on the
    cluster. The second number in any ID.

    For example, in container_1567013493699_0003_01_000002, it's 0003.
    """
    return _id_part(_any_id(d), 2)

def _add_spark_submit_arg(parser, opt_name):
    opt_string = _SPARK_SUBMIT_SWITCHES[opt_name]

    kwargs = dict(dest=opt_name)

    # if opt_name is a mrjob opt, parse args like a MRJob would
    if opt_name in _RUNNER_OPTS:
        opt_alias = _SWITCH_ALIASES.get(opt_string, opt_string)

        for opt_strings, opt_kwargs in _RUNNER_OPTS[opt_name]['switches']:
            if opt_alias in opt_strings:
                kwargs.update(opt_kwargs)

    kwargs['help'] = _SPARK_SUBMIT_ARG_HELP[opt_name]
    kwargs.update(_SPARK_SUBMIT_ARG_KWARGS.get(opt_name) or {})

    parser.add_argument(opt_string, **kwargs)

def _make_basic_help_parser(include_deprecated=False):
    """Make an arg parser that's used only for printing basic help.

    This prints help very similar to spark-submit itself. Runner args
    are not included unless they are also spark-submit args (e.g. --py-files)
    """
    help_parser = ArgumentParser(usage=_USAGE, description=_DESCRIPTION,
                                 epilog=_BASIC_HELP_EPILOG, add_help=False)

    _add_runner_alias_arg(help_parser)

    for group_desc, opt_names in _SPARK_SUBMIT_ARG_GROUPS:
        if group_desc is None:
            parser_or_group = help_parser
        else:
            parser_or_group = help_parser.add_argument_group(group_desc)

        for opt_name in opt_names:
            _add_spark_submit_arg(parser_or_group, opt_name)

        if group_desc is None:
            _add_basic_args(help_parser)
            _add_help_arg(help_parser)
            if include_deprecated:
                _add_deprecated_arg(help_parser)

    return help_parser

def _subdivide_interval_by_date(start, end):
    """Convert a time interval to a map from :py:class:`datetime.date` to
    the number of seconds within the interval on that date.

    *start* and *end* are :py:class:`datetime.datetime` objects.
    """
    if start.date() == end.date():
        date_to_secs = {start.date(): timedelta.total_seconds(end - start)}
    else:
        date_to_secs = {}

        date_to_secs[start.date()] = timedelta.total_seconds(
            datetime(start.year, start.month, start.day, tzinfo=start.tzinfo) +
            timedelta(days=1) - start)

        date_to_secs[end.date()] = timedelta.total_seconds(
            end - datetime(end.year, end.month, end.day, tzinfo=end.tzinfo))

        # fill in dates in the middle
        cur_date = start.date() + timedelta(days=1)
        while cur_date < end.date():
            date_to_secs[cur_date] = timedelta.total_seconds(timedelta(days=1))
            cur_date += timedelta(days=1)

    # remove zeros
    date_to_secs = dict(
        (d, secs) for d, secs in date_to_secs.items() if secs)

    return date_to_secs

def _percent(x, total, default=0.0):
    """Return what percentage *x* is of *total*, or *default* if
    *total* is zero."""
    if total:
        return 100.0 * x / total
    else:
        return default

def _cluster_has_pending_steps(steps):
    """Does *cluster* have any steps in the ``PENDING`` state?"""
    return any(step['Status']['State'] == 'PENDING' for step in steps)

def _time_last_active(cluster_summary, steps):
    """When did something last happen with the given cluster?

    Things we look at:

    * cluster's ``CreationDateTime`` (always set)
    * cluster's ``ReadyDateTime`` (i.e. when bootstrapping finished)
    * step's ``CreationDateTime`` for any step
    * step's ``StartDateTime`` for any step
    * step's ``EndDateTime`` for any step

    This is not really meant to be run on clusters which are currently
    running, or done.
    """
    timestamps = []

    for key in 'CreationDateTime', 'ReadyDateTime':
        value = cluster_summary['Status']['Timeline'].get(key)
        if value:
            timestamps.append(value)

    for step in steps:
        for key in 'CreationDateTime', 'StartDateTime', 'EndDateTime':
            value = step['Status']['Timeline'].get(key)
            if value:
                timestamps.append(value)

    return max(timestamps)

def standardize_phone_number(number):
    """put *number* in a standard format, and convert it to a :py:class:`str`.
    """
    number_sep = PHONE_SEP_RE.split(number)
    number = b''.join(number_sep).decode('ascii')
    if len(number) > 7:
        if number[-1] not in '0123456789':
            number = number[:-1]
        if number[0] not in '0123456789':
            number = number[1:]
    if len(number) <= 10:
        return "+1" + number
    else:
        return "+" + number

def steps(self):
    return [
        MRStep(mapper_raw=self.extract_phone_and_url_mapper,
               reducer=self.count_by_host_reducer),
        MRStep(reducer=self.pick_best_url_reducer),
    ]

def extract_phone_and_url_mapper(self, wet_path, wet_uri):
    """Read in .wet file, and extract phone ant URL
    """
    from warcio.archiveiterator import ArchiveIterator

    with open(wet_path, 'rb') as f:
        for record in ArchiveIterator(f):
            if record.rec_type != 'conversion':
                continue

            headers = record.rec_headers
            if headers.get_header('Content-Type') != 'text/plain':
                continue

            url = headers.get_header('WARC-Target-URI')
            if not url:
                continue

            host = urlparse(url).netloc

            payload = record.content_stream().read()
            for phone in PHONE_RE.findall(payload):
                phone = standardize_phone_number(phone)
                yield host, (phone, url)

def count_by_host_reducer(self, host, phone_urls):
    phone_urls = list(islice(phone_urls, MAX_PHONES_PER_HOST + 1))

    # don't bother with directories, etc.
    host_phone_count = len(phone_urls)
    if host_phone_count > MAX_PHONES_PER_HOST:
        return

    for phone, url in phone_urls:
        yield phone, (url, host_phone_count)

