            MRStep(reducer=self.r_compute_stats)]

def c_combine_counts(self, key, counts):
    """Sum up all those 1s before passing data off to the reducer"""
    yield key, sum(counts)

def parse_doc_filename(input_uri):
    """Parse a filename like ``some_id-cat1-cat2-not_cat3.txt`` into
    ``dict(id='some_id', cats=dict(cat1=True, cat2=True, cat3=False))``
    """
    # get filename without extension
    from mrjob.util import file_ext
    name_with_ext = posixpath.basename(input_uri)
    name = name_with_ext[:-len(file_ext(name_with_ext))]

    parts = name.split('-')

    doc_id = parts[0]
    cats = {}

    for part in parts[1:]:
        if part.startswith('not_'):
            cats[part[4:]] = False
        else:
            cats[part] = True

    return dict(id=doc_id, cats=cats)

def get_words(self, line_iterator):
    # this only happens once per partition
    stop_words = self.load_stop_words()

    for line in line_iterator:
        for word in WORD_RE.findall(line):
            word = word.lower()
            if word not in stop_words:
                yield (word, 1)

def load_stop_words(self):
    # this should only be called inside executors (i.e. inside functions
    # passed to RDDs)
    stop_words_path = self.options.stop_words_file or 'stop_words.txt'

    with open(stop_words_path) as f:
        return set(line.strip() for line in f)

def mapper(self, _, line):
    for word in WORD_RE.findall(line):
        yield (word.lower(), 1)

