def reducer(self, word, counts):
    total = sum(counts)
    yield None, '\t'.join([word[0], json.dumps(word), json.dumps(total)])

def steps(self):
    jar = self.options.examples_jar

    if self.options.use_main_class:
        jar_step = JarStep(
            jar=jar,
            args=[GENERIC_ARGS, INPUT, OUTPUT],
            main_class=_WORDCOUNT_MAIN_CLASS,
        )
    else:
        jar_step = JarStep(
            jar=jar,
            args=['wordcount', GENERIC_ARGS, INPUT, OUTPUT],
        )

    return [
        jar_step,
        MRStep(
            mapper=self.mapper,
            combiner=self.reducer,
            reducer=self.reducer,
        )
    ]

def mapper_get_words(self, _, line):
    # yield each word in the line
    for word in WORD_RE.findall(line):
        word = word.lower()
        if word not in self.stop_words:
            yield (word, 1)

def combiner_count_words(self, word, counts):
    # sum the words we've seen so far
    yield (word, sum(counts))

def reducer_find_max_word(self, _, word_count_pairs):
    # each item of word_count_pairs is (count, word),
    # so yielding one results in key=counts, value=word
    try:
        yield max(word_count_pairs)
    except ValueError:
        pass
